// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Tanzimat, Servetifünun, Fecriati ve Millî Edebiyat dönemleri: roman kahramanları, dergiler, eleştiriler ve edebî tartışmalar (orta).
const ozLiterature15Orta = <(String, String, List<String>, String)>[
  ('Ali Suavi\'nin 1867\'de İstanbul\'da çıkarıp daha sonra Londra\'da yayımlamayı sürdürdüğü, \'doğru söz söylemenin yasak olmadığı bir memlekette Türkçe gazete basmak\' fikriyle öne çıkan yayın hangisidir?', 'Muhbir', ['Meşveret', 'Tercüman-ı Hakikat', 'Servet-i Fünun'], 'Ali Suavi önce İstanbul\'da çıkardığı Muhbir gazetesini sürgün sonrası Londra\'da Yeni Osmanlılar adına yayımlamıştır.'),
  ('Şair Evlenmesi\'nde Müştak Bey\'in yakın dostu olup mahalle imamı Ebullaklaka\'ya para kesesi uzatarak \'yaşça büyük kız yerine boyca büyük kız\' kastedildiğini onaylatan ve düğümü çözen karakter kimdir?', 'Hikmet Efendi', ['Atak Köse', 'Batak Ese', 'Ziba Dudu'], 'Hikmet Efendi, Müştak Bey\'in sağduyulu dostudur ve Ebullaklaka\'ya rüşvet vererek Kumru Hanım ile evlenmesini sağlar.'),
  ('Şinasi\'nin Şair Evlenmesi adlı oyununda mahallenin temizlik işçisi \'Atak Köse\' veya bekçi \'Batak Ese\' gibi adlandırmalar kullanması hangi geleneğin izlerini taşır?', 'Geleneksel Türk seyirlik oyunlarındaki tip ve isim komiğinin', ['Fransız trajedilerindeki soylu kahraman adlandırma kuralının', 'Divan mesnevilerindeki sembolik tasavvuf mazmunlarının', 'Yunan mitolojisindeki yarı tanrısal koro karakterlerinin'], 'Şinasi Batılı komedi tekniğini orta oyunu ve Karagöz\'deki lakap/tip geleneğiyle birleştirmiştir.'),
  ('Yusuf Kâmil Paşa\'nın Fransız yazar Fénelon\'dan 1859\'da çevirdiği ve edebiyatımızda Batı\'dan yapılan ilk roman çevirisi kabul edilen Tercüme-i Telemak, dil ve üslup bakımından nasıl bir özellik gösterir?', 'Ağır, secili ve süslü divan nesri geleneğine bağlı kalınarak kaleme alınmıştır', ['Halk söyleyişlerine dayalı yalın bir İstanbul Türkçesiyle aktarılmıştır', 'Kafiyeli beyitler hâlinde aruz vezniyle manzum olarak tercüme edilmiştir', 'Noktalama işaretlerinin ilk kez eksiksiz kullanıldığı sade bir metindir'], 'Tercüme-i Telemak içerik olarak Batılı bir siyasetname/roman olsa da üslupça klasik inşâ (süslü nesir) geleneğindedir.'),
  ('Şemsettin Sami\'nin 1872\'de yayımladığı ilk yerli romanımız Taaşşuk-ı Talat ve Fitnat\'ta, üvey kızı Fitnat\'ı konağa kapatıp hiç tanımadığı zengin Ali Bey ile zorla evlendirmeye çalışan üvey baba kimdir?', 'Hacı Mustafa', ['Salih Efendi', 'Süleyman Bey', 'Kasım Efendi'], 'Taaşşuk-ı Talat ve Fitnat\'ta Fitnat\'ı dış dünyadan koparıp Ali Bey\'le evlendiren baskıcı üvey baba Hacı Mustafa\'dır.'),
  ('Taaşşuk-ı Talat ve Fitnat romanının sonunda trajediyi doruğa çıkaran ve hem Fitnat\'ın intiharına hem de Talat\'ın kederinden ölmesine yol açan dramatik tesadüf nedir?', 'Fitnat\'ın zorla nikâhlandığı Ali Bey\'in aslında onun öz babası çıkması', ['Talat ile Fitnat\'ın bebekken ayrılmış ikiz kardeş olduklarının anlaşılması', 'Kadın kılığına giren Talat\'ın yanlışlıkla düelloda Fitnat\'ı yaralaması', 'Hacı Mustafa\'nın tüm mirası sahte belgelerle tefecilere kaptırması'], 'Ali Bey, Fitnat\'ın boynundaki muskayı görünce onun yıllar önce terk ettiği eşi Zekiye\'den doğan öz kızı olduğunu anlar; ancak Fitnat çoktan hançerle canına kıymıştır.'),
  ('Namık Kemal\'in İntibah romanında bölüm başlarına divan şairlerinden beyitler koyması, uzun Çamlıca tasvirleri yapması ve iyileri mutlak iyi, kötüleri mutlak kötü çizmesi hangi akımın etkisini kanıtlar?', 'Romantizm akımının duygu, tezat ve öznellik ilkelerinin', ['Natüralizm akımının soyaçekim ve deneysel gözlem anlayışının', 'Klasisizm akımının akıl, sağduyu ve yüksek zümre kurallarının', 'Parnasizm akımının nesnel ve dış gerçekliğe bağlı betimlemelerinin'], 'Namık Kemal, Victor Hugo etkisindeki romantizm akımına bağlıdır; keskin iyi-kötü çatışması ve öznel doğa betimlemeleri romantizmin özelliğidir.'),
  ('Namık Kemal\'in 1880\'de yayımladığı ilk tarihî romanımız Cezmi\'de, Osmanlı-İran savaşları sırasında dostluk kuran şair ruhlu sipahi Cezmi ile Kırım şehzadesi kimdir?', 'Adil Giray', ['Gazi Giray', 'İslam Giray', 'Şahin Giray'], 'Cezmi romanında başkahraman Cezmi, İran\'a esir düşen Kırım şehzadesi Adil Giray\'ı kurtarmaya çalışır.'),
  ('Namık Kemal\'in 1 Nisan 1873\'te Gedikpaşa Tiyatrosu\'nda sahnelendiğinde halkta büyük coşku uyandırıp yazarının Magosa\'ya sürgün edilmesine yol açan Vatan yahut Silistre oyununda kuşatılan kalenin komutanı kimdir?', 'Sıtkı Bey', ['Rüstem Bey', 'Akif Bey', 'Muhtar Paşa'], 'Silistre Kalesi komutanı Sıtkı Bey olup oyunun sonunda Zekiye\'nin yıllar önce kaybettiği öz babası olduğu ortaya çıkar.'),
  ('Vatan yahut Silistre oyununda \'Kıyamet kopar mı, kale teslim olur mu?\' sözünü sürekli tekrarlayarak hem mizahi hem de kahramanca bir tip çizen karakter hangisidir?', 'Abdullah Çavuş', ['İslam Bey', 'Hüsrev Ağa', 'Zülfikar Ağa'], 'Abdullah Çavuş, her koşulda soğukkanlılığını koruyan ve \'Kıyamet mi kopar?\' repliğiyle özdeşleşen fedakâr asker tipidir.'),
  ('Namık Kemal\'in \'Tiyatroyu eğlencelerin en faydalısı sayarım\' görüşünü savunarak dram türünün ilkelerini ve kendi sanat anlayışını açıkladığı ünlü önsöz hangi eserinin başında yer alır?', 'Celaleddin Harzemşah', ['Zavallı Çocuk', 'Kara Bela', 'Gülnihal'], 'Namık Kemal, Victor Hugo\'nun Cromwell önsözüne benzer biçimde tiyatro ve edebiyat görüşlerini Celaleddin Harzemşah mukaddimesinde açıklamıştır.'),
  ('Namık Kemal\'in \'Raz-ı Dil\' adıyla da bilinen, zalim sancak beyi Kaplan Paşa\'nın zulmüne karşı Muhtar Bey ve İsmet Hanım\'ın mücadelesini dadı karakteri üzerinden anlatan piyesi hangisidir?', 'Gülnihal', ['Akif Bey', 'Kara Bela', 'Çok Bilen Çok Yanılır'], 'Asıl adı Raz-ı Dil olan ancak sansürce Gülnihal\'e çevrilen eserde Kaplan Paşa\'nın istibdadına karşı mücadele işlenir.'),
  ('Namık Kemal\'in Zavallı Çocuk adlı tiyatro eserinde, tıp öğrencisi Ata\'yı sevmesine rağmen ailesinin borçları yüzünden kırk yaşındaki Halil Paşa ile nikâhlandırılınca verem olup ölen genç kız kimdir?', 'Şefika', ['Dilruba', 'Behrever', 'Ferhunde'], 'Zavallı Çocuk\'ta on dört yaşındaki Şefika, Ata\'ya olan aşkını gizleyip ailesi için Paşa ile evlendirilince vereme yakalanır; Ata da eczaneden aldığı zehirle onun yanında intihar eder.'),
  ('Namık Kemal\'in Kırım Savaşı sırasında Sinop baskınında şehit düştüğü sanılan bir deniz subayının, döndüğünde karısı Dilruba\'nın başka biriyle evlenmek üzere olduğunu görmesini konu alan eseri hangisidir?', 'Akif Bey', ['Vatan yahut Silistre', 'Ecel-i Kaza', 'İçli Kız'], 'Akif Bey piyesinde deniz subayı Akif Bey\'in sadakatsiz eşi Dilruba\'nın entrikaları ve babası Süleyman Kaptan\'ın intikamı işlenir.'),
  ('Ziya Paşa\'nın Şiir ve İnşa makalesindeki halk edebiyatı taraftarı görüşlerinden çark ederek halk şairlerinin dizelerini \'eşek anırmasına\' (nehîk-i ebu\'l-meârik) benzettiği antoloji önsözü hangisidir?', 'Harabat Mukaddimesi', ['Tercüme-i Manzume Önsözü', 'Tahrib-i Harabat Risalesi', 'Talim-i Edebiyat Girişi'], 'Ziya Paşa 1874\'te yayımladığı üç ciltlik Harabat antolojisinin manzum mukaddimesinde divan şiirini yüceltip halk şiirini küçümsemiştir.'),
  ('Ziya Paşa\'nın Londra\'da bulunduğu sırada Sultan Abdülaziz ile bir parkta karşılaşarak ülkenin yönetim sorunlarını ve Âli Paşa\'nın icraatlarını tartıştığı kurgusal mülakat eseri aşağıdakilerden hangisidir?', 'Rüya', ['İntibah', 'Muhayyelat', 'Müsameretname'], 'Ziya Paşa\'nın Rüya adlı eseri, mülakat/röportaj tekniğine yaklaşan kurgusal bir siyasi diyalog ve eleştiri metnidir.'),
  ('Ziya Paşa\'nın Jean-Jacques Rousseau\'nun Émile adlı eserini Türkçeye çevirirken kendi çocukluk hatıralarını anlattığı önsöz niteliğindeki bölüm sonradan hangi adla yayımlanmıştır?', 'Defter-i Amal', ['Ömer\'in Çocukluğu', 'Jurnal', 'Saray ve Ötesi'], 'Defter-i Amal, Batılı anlamda anı türünün ilk örneklerinden olup Ziya Paşa\'nın çocukluk yıllarını içerir.'),
  ('Namık Kemal\'in 1866\'da Tasvir-i Efkâr\'da yayımladığı ve edebiyatımızın ilk edebî eleştiri yazısı sayılan makalesinde divan edebiyatına yönelttiği başlıca itiraz nedir?', 'Dilinin halktan kopuk olması ve gerçeklikten uzak abartılı mazmunlarla anlamı boğması', ['Yalnızca kahramanlık ve savaş konularını işleyip bireysel aşk duygusuna hiç yer vermemesi', 'Batı dillerinden çok sayıda teknik terim alarak Arapça ve Farsça kuralları bozması', 'Tiyatro sahnesine uyarlanacak diyaloglara gereğinden fazla ağırlık tanıması'], 'Namık Kemal \'Lisân-ı Osmanînin Edebiyatı Hakkında Bazı Mülahazâtı Şâmildir\' makalesinde divan edebiyatının soyut, gerçek dışı ve ağır dilini eleştirmiştir.'),
  ('Felatun Bey ile Rakım Efendi romanında çalışkan, tutumlu ve Doğu-Batı sentezini başarmış Rakım Efendi\'nin satın alıp eğittiği, piyano çalmayı ve okumayı öğrettiği Çerkez cariyenin adı nedir?', 'Canan', ['Polini', 'Jozefino', 'Mihriban'], 'Rakım Efendi cılız ve hasta bir esir kız olan Canan\'ı satın alır, dadısı Fedayi ile birlikte büyütüp eğitir ve sonunda onunla evlenir.'),
  ('Ahmet Mithat Efendi\'nin Alexandre Dumas\'nın Monte Kristo Kontu romanına nazire olarak kaleme aldığı ve ilk macera romanlarımızdan sayılan eseri hangisidir?', 'Hasan Mellah yahut Sır İçinde Esrar', ['Henüz On Yedi Yaşında', 'Dünyaya İkinci Geliş', 'Çengi'], '1874 tarihli Hasan Mellah, korsanlar, deniz yolculukları ve İspanya\'ya uzanan aşk serüveniyle Monte Kristo Kontu\'na nazire bir macera romanıdır.'),
  ('Ahmet Vefik Paşa\'nın Anadolu Türkçesinin (Osmanlı Türkçesinin) büyük Türk dil ailesinin bir kolu olduğunu belirten sözlüğü ile Ebulgazi Bahadır Han\'dan Çağataycadan aktardığı tarih eseri hangileridir?', 'Lehçe-i Osmanî ve Şecere-i Türkî', ['Kamus-ı Türkî ve Kutadgu Bilig', 'Lügat-i Naci ve Kısas-ı Enbiya', 'Lehçetü\'l-Hakayık ve Fezleke'], 'Ahmet Vefik Paşa Türkçülük bilincine katkı sunan Lehçe-i Osmanî sözlüğünü hazırlamış ve Şecere-i Türkî\'yi Türkiye Türkçesine çevirmiştir.'),
  ('Direktör Ali Bey\'in sözcüklere alaycı ve iğneleyici karşılıklar vererek oluşturduğu Türk edebiyatının ilk mizahi sözlüğü aşağıdakilerden hangisidir?', 'Lehçetü\'l-Hakayık', ['Durub-ı Emsal-i Osmaniye', 'Galatat-ı Tercüme', 'Müntehabat-ı Eş\'ar'], 'Direktör Ali Bey\'in Lehçetü\'l-Hakayık adlı eseri, toplumsal eleştiri içeren nükteli tanımlardan oluşan ilk mizahi sözlüktür.'),
  ('Direktör Ali Bey\'in Molière\'in Scapin\'in Dolapları adlı komedisinden uyarladığı oyun ile Düyun-ı Umumiye müfettişliği sırasında Hindistan ve Bağdat gezilerini günlük biçiminde yazdığı eser hangisidir?', 'Ayyar Hamza ve Seyahat Jurnali', ['Kokona Yatıyor ve Hac Yolunda', 'Geveze Berber ve Mir\'at-ı Memalik', 'Misafiri İstiskal ve Hindistan Mektupları'], 'Direktör Ali Bey\'in en ünlü Molière uyarlaması Ayyar Hamza, ilk günlük (jurnal) örneği sayılan gezi-günlük eseri ise Seyahat Jurnali\'dir.'),
  ('Şemsettin Sami\'nin Türkçenin söz varlığını saptamak amacıyla hazırladığı Kamus-ı Türkî dışında, altı ciltlik tarih ve coğrafya ansiklopedisi niteliği taşıyan dev eseri hangisidir?', 'Kamusü\'l-A\'lâm', ['Keşfü\'z-Zünun', 'Mir\'atü\'l-Memalik', 'Mecelle-i Ahkâm'], 'Şemsettin Sami\'nin Kamusü\'l-A\'lâm\'ı, bizde tek bir yazar tarafından hazırlanmış ilk kapsamlı tarih, coğrafya ve ünlü kişiler ansiklopedisidir.'),
  ('Şemsettin Sami\'nin Arnavut halkının \'verilen sözü canı pahasına tutma\' geleneğini Fettah Ağa\'nın kendi oğlunu vurması üzerinden işlediği trajedisi hangisidir?', 'Besa yahut Ahde Vefa', ['Gavè', 'Seydi Yahya', 'Ecel-i Kaza'], 'Besa yahut Ahde Vefa\'da Arnavutların yemin/söz (besa) geleneği uğruna Fettah Ağa kız kaçıran öz oğlunu öldürüp ardından kendi canına kıyar.'),
  ('Şinasi\'nin Münacat ve Reşit Paşa kasidelerinde divan şiiri geleneğinde yaptığı biçim ve içerik yeniliği aşağıdakilerden hangisidir?', 'Klasik kasidenin nesib ve fahriye gibi bölümlerini atlayıp akıl, adalet ve kanun kavramlarını işlemesi', ['Aruz ölçüsünü tamamen bırakarak kasideleri on birli hece ölçüsüyle kaleme alması', 'Beyit birimini terk edip sone ve terzarima nazım biçimlerini ilk kez denemesi', 'Şiirlerinde noktalama işaretleri yerine renkli hat süslemeleri kullanması'], 'Şinasi, Mustafa Reşit Paşa\'ya yazdığı kasidelerde klasik övgü kalıplarını kırarak Paşa\'yı \'medeniyet resulü\', kanun ve akıl temsilcisi olarak övmüştür.'),
  ('Sadullah Paşa\'nın Berlin elçiliği yıllarında yazdığı ve bilim-teknoloji alanındaki buluşları (buhar gücü, telgraf, yerçekimi) coşkuyla yücelterek pozitivist ilerleme fikrini savunduğu ünlü manzumesi hangisidir?', 'Ondokuzuncu Asır', ['Hürriyet Kasidesi', 'Küre-i Arz', 'Vaveyla'], 'Sadullah Paşa\'nın Ondokuzuncu Asır kasidesi \'Erişti evc-i kemâlâta nûr-ı idrâkât\' mısraıyla Batı bilimini ve aydınlanmayı yüceltir.'),
  ('Giritli Ali Aziz Efendi\'nin 18. yüzyıl sonunda yazdığı ancak 1852\'de basılmasıyla Tanzimat romancılığını etkileyen, üç ayrı \'Hayal\' bölümünden oluşan fantastik-geleneksel anlatısı hangisidir?', 'Muhayyelat', ['Hüsn ü Aşk', 'İntibah', 'Sergüzeşt'], 'Ali Aziz Efendi\'nin Muhayyelat-ı Aziz Efendi eseri, klasik kıssa geleneğinden Tanzimat romanına (özellikle Ahmet Mithat\'a) köprü kurmuştur.'),
  ('Tanzimat I. Dönem sanatçılarının dilde sadeleşmeyi savunmalarına rağmen eserlerinde bu hedefi tam olarak gerçekleştirememelerinin temel nedeni nedir?', 'Divan edebiyatı kültürüyle yetişmeleri ve yeni kavramları karşılayacak işlenmiş bir yazı dilinin henüz oturmaması', ['Gazete okurlarının sade Türkçe metinleri protesto ederek aboneliklerini iptal etmeleri', 'Encümen-i Daniş kurumunun Arapça ve Farsça tamlamalar dışındaki sözcükleri yasaklaması', 'Servetifünun şairlerinin salon edebiyatı anlayışını onlara zorla kabul ettirmesi'], 'Şinasi, Namık Kemal ve Ziya Paşa sadeleşmeyi kuramsal olarak savunsalar da aldıkları klasik medrese/kalem eğitimi nedeniyle tamlamalı dilden tam kopamamışlardır.'),
  ('Encümen-i Daniş kararıyla Cevdet Paşa ve Fuat Paşa tarafından 1851\'de hazırlanan ve Türkiye\'de basılan ilk Türkçe dil bilgisi kitabı kabul edilen eser hangisidir?', 'Kavaid-i Osmaniyye', ['Sarf-ı Türkî', 'Müyessiretü\'l-Ulûm', 'Muhakemetü\'l-Lügateyn'], 'Ahmet Cevdet Paşa ile Keçecizade Fuat Paşa\'nın birlikte yazdığı Kavaid-i Osmaniyye, modern dönemde hazırlanan ilk Osmanlı Türkçesi grameridir.'),
  ('Ahmet Cevdet Paşa\'nın on iki ciltlik Tarih-i Cevdet ile İslam medeniyetini anlattığı Kısas-ı Enbiya dışında, Osmanlı özel hukukunu sistemleştiren büyük hukuk külliyatı hangisidir?', 'Mecelle-i Ahkâm-ı Adliye', ['Kanun-ı Esasi', 'Düsturü\'l-Amel', 'Tezakir'], 'Ahmet Cevdet Paşa başkanlığındaki heyetin hazırladığı Mecelle, Osmanlı\'nın ilk medeni kanunu niteliğindeki büyük hukuk metnidir.'),
  ('Namık Kemal\'in 1872\'de İstanbul\'a döndükten sonra arkadaşlarıyla kiralayıp başyazarı olduğu, sert muhalefeti nedeniyle defalarca kapatılan fikir gazetesi hangisidir?', 'İbret', ['Takvim-i Vekayi', 'Malumat', 'İkdam'], 'Namık Kemal Avrupa dönüşü İbret gazetesinde \'Aile, Hukuk, İstikbal\' gibi etkili makaleler yazmış; Vatan yahut Silistre olayıyla gazete temelli kapatılmıştır.'),
  ('Şinasi\'nin La Fontaine\'den esinlenerek yazdığı \'Eşek ile Tilki Hikâyesi\' ve \'Tenasüh\' gibi fabl örnekleri hangi şiir kitabında yer almıştır?', 'Müntehabat-ı Eş\'ar', ['Tercüme-i Manzume', 'Şermin', 'Nesteren'], 'Şinasi kendi telif şiirlerini ve La Fontaine tarzı manzum fabllarını 1862\'de yayımladığı Müntehabat-ı Eş\'ar (Şiir Seçkisi) kitabında toplamıştır.'),
  ('Namık Kemal\'in Kanije Kalesi müdafaasını, Devr-i İstila\'yı ve Bârika-i Zafer\'i kaleme almasındaki ortak tarihsel ve edebî amaç nedir?', 'Osmanlı tarihinin parlak zaferlerini hatırlatarak sarsılan özgüveni ve vatanperverlik ruhunu canlandırmak', ['Saray vakanüvislerinin maaş sistemini eleştirip resmi tarih yazıcılığını sona erdirmek', 'Avrupa devletlerinin askeri taktiklerini tercüme ederek Harbiye Mektebi\'ne ders kitabı hazırlamak', 'İslam öncesi Orta Asya Türk destanlarını derleyerek Turancılık ülküsünü temellendirmek'], 'Namık Kemal, Evrak-ı Perişan serisinde (Selahaddin Eyyubi, Fatih, Yavuz) ve Kanije gibi eserlerinde şanlı Osmanlı-İslam kahramanlarıyla milli heyecan uyandırmayı amaçlamıştır.'),
  ('Şemsettin Sami\'nin \'Lisan-ı Türki (Osmani)\' başlıklı makalesinde savunduğu ve çağdaşlarından çok daha ileri bir dil bilincini yansıtan görüşü hangisidir?', 'Osmanlıca adlandırmasının yanlış olduğu; konuştuğumuz dilin Doğu Türkçesiyle aynı kökten gelen Türkçe olduğu', ['Arap alfabesinin derhal bırakılıp Kiril harflerine geçilmesinin zorunlu sayıldığı', 'Arapça ve Farsça kelimelerin tamamının atılıp yalnızca Moğolca eklerin kullanılması gerektiği', 'İstanbul ağzının yapay olduğu ve yazı dilinin Bakü lehçesi üzerine kurulması gerektiği'], 'Şemsettin Sami \'üç dilden mürekkep bir lisan olamayacağını\', dilimizin adının \'Lisan-ı Türkî\' olduğunu ve sadeleşmesi gerektiğini bilimsel olarak savunmuştur.'),
  ('Güllü Agop\'un 1868\'de Gedikpaşa\'da kurduğu Osmanlı Tiyatrosu\'nun 1870\'te Sadrazam Âli Paşa\'dan aldığı on yıllık imtiyaz (tekel hakkı) neyi kapsıyordu?', 'İstanbul\'da Türkçe oyun sahneleme yetkisinin belirli kurallarla yalnızca bu tiyatroya verilmesini', ['Avrupa\'dan gelen Fransız ve İtalyan opera kumpanyalarının vergiden muaf tutulmasını', 'Saray dışındaki tüm meddah ve Karagöz gösterilerinin süresiz olarak yasaklanmasını', 'Yalnızca çeviri oyunların oynanmasını ve yerli yazarların telif eser vermesinin engellenmesini'], 'Güllü Agop, tiyatroyu yaygınlaştırma ve yeni sahneler açma şartıyla İstanbul\'da Türkçe tiyatro oynatma konusunda 10 yıllık tekel imtiyazı almıştır; bu da yazarlarımızı oyun yazmaya yöneltmiştir.'),
  ('Namık Kemal\'in İrfan Paşa\'ya Mektup ve Mukaddime-i Celal dışında, Magosa, Midilli ve Rodos sürgünlerinde dostlarına, babasına ve kızı Feride\'ye yazdığı mektupların edebî önemi nedir?', 'Samimi üslubuyla özel mektup türünün ve edebiyat tarihi belgelerinin en zengin örneklerini oluşturması', ['Tamamının Fransızca kaleme alınarak Avrupa gazetelerinde açık bildiri olarak basılması', 'Roman kahramanlarının uydurma mektuplarından oluşan kurmaca bir anlatı bütünlüğü taşıması', 'Divan inşâ geleneğindeki münşeat mecmualarının süslü secilerini yeniden canlandırması'], 'Namık Kemal\'in yüzlerce mektubu, hem özel mektup türünün canlı örnekleridir hem de dönemin edebî-siyasi tartışmalarını aydınlatan birinci el kaynaklardır.'),
  ('Ziya Paşa\'nın \'Âyînesi iştir kişinin lâfa bakılmaz / Şahsın görünür rütbe-i aklı eserinde\' gibi halk arasında atasözü değerine ulaşan beyitlerinin çokluğu onun hangi üslup özelliğine bağlanır?', 'Hikemî şiir (Nâbî okulu) geleneğini sürdürerek felsefi ve ahlaki özdeyişler söylemedeki ustalığına', ['Sebk-i Hindî tarzında anlaşılması güç, katmanlı ve hayale dayalı imgeler kurmasına', 'Âşık tarzı koşmalarda sade halk deyimlerini dörtlük sonlarında nakarat yapmasına', 'Parnasizm etkisiyle dış doğayı duygudan arınmış plastik bir dille betimlemesine'], 'Ziya Paşa divan şiirindeki hikemî (didaktik-felsefi) tarzın 19. yüzyıldaki en güçlü temsilcisidir ve pek çok dizesi irsal-i mesel/vecize niteliği kazanmıştır.'),
  ('Namık Kemal\'in İntibah romanında Ali Bey\'in varlıklı ve kültürlü bir aileden gelmesine karşın Mahpeyker\'in tuzağına hızla düşmesini yazar hangi pedagojik eksikliğe bağlar?', 'Aşırı korumacı büyütüldüğü için gerçek hayatı ve insan sarraflığını hiç tanımamış olmasına', ['Avrupa\'da kumarhanelere alışıp babasının mirasını daha çocukken tüketmiş olmasına', 'Hiç okuma yazma bilmediği için sahte borç senetlerini fark edememesine', 'Askerlik mesleğinin sert disiplini yüzünden duygusal boşluğa sürüklenmesine'], 'Ali Bey kitabi bilgilere sahip ama hayat tecrübesi olmayan saf bir gençtir; babasının ölümü sonrası annesi Fatma Hanım onu oyalamak için Çamlıca\'ya götürdüğünde ilk gördüğü kadına kapılır.'),
  ('Şinasi\'nin \'Vahdet-i zâtına aklımca şehâdet lâzım / Can ü gönlümle münâcât ü ibâdet lâzım\' beytinde görülen dini-felsefi tutum, klasik münacatlardan hangi noktada ayrılır?', 'Tanrı\'nın varlığına ve birliğine gönül sezgisi yanında akıl yoluyla ulaşma fikrini öne çıkarmasıyla', ['Evrenin tesadüfen oluştuğunu ileri sürerek materyalist bir doğa görüşü savunmasıyla', 'Peygamber mucizelerini mitolojik efsanelerle birleştirerek epik bir dil kurmasıyla', 'İbadet biçimlerini tamamen reddedip yalnızca doğa gezintilerini öğütlemesiyle'], 'Klasisizm ve Aydınlanma Çağı rasyonalizminden etkilenen Şinasi, Münacat\'ında Tanrı\'nın birliğini \'akıl\' kavramıyla kavrama vurgusu yapmıştır.'),
  ('Araba Sevdası\'nda Bihruz Bey\'in daireden arkadaşı olup söylediği yalanlarla Periveş\'in tifodan öldüğüne onu inandıran ve alaycı kişiliğiyle olayları karıştıran karakter kimdir?', 'Keşfi Bey', ['Mösyö Pierre', 'Şevket Efendi', 'Müştak Bey'], 'Yalancılığıyla tanınan Keşfi Bey, Bihruz Bey\'den kurtulmak için Periveş\'in öldüğü yalanını uydurur ve Bihruz\'u mezar arama komedisine sürükler.'),
  ('Araba Sevdası\'nda Bihruz Bey\'in Periveş\'e vermek üzere Fransızca şiir ve sözlüklerden derlemeye çalıştığı mektupta \'siyah\' anlamındaki \'noir\' sözcüğünü bir tür adı sanarak düştüğü gülünç yanılgı neyi simgeler?', 'Kültürü özümsemeden taklit eden yarım aydınların yüzeyselliğini', ['Matbaa dizgicilerinin yabancı harfleri yanlış basmasından doğan hataları', 'Fransız öğretmenlerin Türk gençlerine kasıtlı olarak bozuk dil öğretmesini', 'Divan şiirindeki mazmunların Batı dillerine çevrilmesindeki imkânsızlığı'], 'Bihruz Bey ansiklopedi ve antolojideki şair adını ya da dipnot kısaltmasını anlamayıp \'sarışın\' Periveş\'e \'siyah\' sıfatıyla hitap edecek kadar bilgisizdir.'),
  ('Recaizade Mahmut Ekrem\'in Araba Sevdası\'nı Felatun Bey ile Rakım Efendi\'den ayıran ve eseri realist romana yaklaştıran en önemli teknik özellik nedir?', 'Bihruz Bey\'in karşısına ders verici ideal bir karşıt tip çıkarmayıp yazarın kişiliğini gizlemesi', ['Olayları İstanbul dışına taşıyarak Anadolu köylüsünün geçim sıkıntısını belgelemesi', 'Kahramanların tamamını yüksek ahlaklı ve kusursuz vatanseverler arasından seçmesi', 'Bölüm sonlarında okura doğrudan seslenerek iktisat ve tasarruf öğütleri sıralaması'], 'Ahmet Mithat Felatun\'un karşısına ideal Rakım\'ı koyup müdahale ederken, Recaizade Bihruz\'u kendi iç dünyası, yanılsamaları ve Çamlıca gözlemleriyle nesnel-ironik biçimde işler.'),
  ('Sergüzeşt romanında Asaf Paşa konağında resim yapan genç Celal Bey\'in Dilber\'e çeşitli kıyafetler giydirerek tablolarını çizmesi hangi duygusal dönüşümü başlatır?', 'Başlangıçta model olarak gördüğü esir kıza zamanla derin bir aşkla bağlanmasını', ['Dilber\'in resim yeteneğini keşfederek onu Paris Güzel Sanatlar Okuluna göndermesini', 'Konaktaki Fransız mürebbiyenin tabloları çalarak sergi açıp zengin olmasını', 'Asaf Paşa\'nın oğlunu evlatlıktan reddedip tüm mirasını hayır kurumlarına bağışlamasını'], 'Avrupa\'da eğitim görmüş ressam Celal Bey, önce sanat modeli olarak kullandığı Dilber\'in masumiyetini ve acısını fark ederek ona âşık olur.'),
  ('Sergüzeşt romanının sonunda Mısır\'da zengin bir tüccarın konağına satılan Dilber\'i karanlık odadan kurtarmaya çalışırken merdivenden düşüp ölen sadık harem ağası ve ardından Dilber\'in sonu nasıl gelişir?', 'Cevher Ağa merdivenden düşüp ölünce çaresiz kalan Dilber kendini Nil Nehri\'ne atar', ['Abdullah Çavuş nöbetçileri vururken Dilber gizlice İskenderiye vapuruna biner', 'Ahşid Ağa konak sahibini zehirleyince Dilber mahkemede yargılanıp hapse atılır', 'Mercan Ağa tüm altınlarını vererek Dilber\'in azat belgesini satın alıp onu evlendirir'], 'Harem ağası Cevher, Dilber\'i pencereden ip merdivenle kaçırırken düşüp can verir; tek başına İstanbul\'a dönemeyeceğini anlayan Dilber, Nil sularında intihar eder.'),
  ('Sami Paşazade Sezai\'nin Küçük Şeyler kitabındaki \'Pandomima\' öyküsünde, dış görünüşüyle herkesi güldürürken iç dünyasında karşılıksız aşkıyla yıkılan yalnız karakter kimdir?', 'Paskal', ['Mişon', 'Mösyö Kanguru', 'Aleko'], 'Pandomima öyküsünde şişman ve çirkin pandomim sanatçısı Paskal, seyircisi Eftalya\'ya gizlice âşık olur; Eftalya\'nın evlendiğini öğrenince evinde intihar eder.'),
  ('Nabizade Nazım\'ın 1890\'da yayımladığı ve edebiyatımızın ilk köy romanı (uzun öyküsü) kabul edilen Karabibik\'te olaylar hangi coğrafi bölgede geçmektedir?', 'Antalya\'nın Kaş ilçesine bağlı Beymelek köyünde', ['Eskişehir\'in Porsuk Çayı kıyısındaki orta Anadolu bozkırında', 'Bursa\'nın Uludağ eteklerindeki ipek böcekçiliği yapılan bir ovada', 'Aydın\'ın Söke ovasındaki büyük pamuk çiftliklerinden birinde'], 'Askeri görevle Antalya-Kaş yöresinde bulunan Nabizade Nazım, Karabibik\'in mekanını Kaş\'ın Beymelek ve Temre (Demre) köyleri olarak seçmiştir.'),
  ('Karabibik eserinde başkahraman Karabibik\'in yaşamındaki en büyük ekonomik tutkusu ve kızını Yosturoğlu\'nun yeğeni Hüseyin\'e verirken güttüğü hesap nedir?', 'Komşusundan öküz kiralamaktan kurtulup bir çift öküz satın alarak tarlasını kendisi sürebilmek', ['Köy muhtarlığını Koca İmam\'ın elinden alıp vergi toplama yetkisini ele geçirmek', 'Antalya limanında Rum tüccarlarla ortak bir zeytinyağı sabunhanesi açmak', 'Askerlik bedelini ödeyerek İstanbul\'daki konaklardan birine kâhya yazılmak'], 'Karabibik tarlasını sürmek için her yıl Koca İmam\'ın öküzlerine muhtaçtır; kızı Huri\'yi Hüseyin\'le evlendirip hem Yosturoğlu ile çekişmeyi bitirmek hem de Rum bakkal Yani\'den borçla öküz almak ister.'),
  ('Abdülhak Hamit\'in 1879\'da yayımlanan ve Türk edebiyatında Batılı anlamda ilk pastoral şiir kitabı kabul edilen Sahra\'da \'Hoşnişinân\' ve \'Belde\' bölümleri hangi karşıtlığı işler?', 'Doğayla uyumlu saf kır yaşamı ile yapay ve yozlaşmış büyükşehir hayatı arasındaki tezadı', ['Doğu ordularının cesareti ile Avrupa devletlerinin teknolojik silah üstünlüğü arasındaki farkı', 'Medrese eğitiminin ezberciliği ile modern mülkiye mekteplerinin deneysel yöntemi arasındaki çatışmayı', 'Eski Yunan mitolojisi ile İran şehname efsaneleri arasındaki kahramanlık anlayışı farkını'], 'Rousseau etkisindeki Sahra\'da \'Hoşnişinân\' doğadaki sade ve mutlu köylüyü yüceltirken, \'Belde\' Paris merkezli yapay şehir uygarlığını eleştirir.'),
  ('Abdülhak Hamit Tarhan\'ın 1913\'te yayımlanan ve Türk şiirinde uyak kullanılmadan (kafiyesiz) kaleme alınmış ilk uzun manzume sayılan yapıtı hangisidir?', 'Validem', ['Hacle', 'Ölü', 'Baladan Bir Ses'], 'Hamit\'in okuma yazma bilmeyen Kafkasyalı annesi Münteha Hanım\'ın hayatını ve hayallerini anlattığı Validem, ilk kafiyesiz şiirimiz kabul edilir.'),
  ('Abdülhak Hamit\'in 1878\'de Paris\'teyken Fransız şair Corneille\'in \'Le Cid\' adlı eserinden esinlenerek hece ölçüsüyle yazdığı, Kabil ve Gazne hükümdarları arasındaki onur-aşk çatışmasını işleyen piyesi hangisidir?', 'Nesteren', ['Sabr u Sebat, atasözleriyle örülü mensur oyun', 'İçli Kız, üvey anne zulmünü anlatan aile dramı', 'Macera-yı Aşk, Keşmir\'de geçen ilk tiyatro denemesi'], 'Nesteren, Corneille\'in Le Cid trajedisine nazire olarak duraksız hece vezniyle (mukaffa) yazılmış manzum bir dramdır.'),
  ('Abdülhak Hamit\'in Londra sosyetesini fon aldığı, Kanadalı hırslı bir kadın olan başkahramanın uşağı Hintli Davalaciro aracılığıyla çevirdiği entrikaları Shakespeare etkisiyle işlediği eseri hangisidir?', 'Finten', ['Tarık yahut Endülüs Fethi', 'Sardanapal', 'Tezer'], 'Finten, Londra\'daki yüksek cemiyetin ikiyüzlülüğünü, vahşi tutkuları ve Davalaciro\'nun kıskançlığını Othello ve Macbeth havasında işleyen manzum-mensur tiyatrodur.'),
  ('Abdülhak Hamit\'in Endülüs\'ü fetheden İslam komutanının hazine dairesindeki ganimetler karşısında söylediği \'Her yer karanlık pür-nur o mevki\' mısraıyla ünlü \'Merkad-i Fatih\'i Ziyaret\' dışındaki İspanya konulu şaheseri hangisidir?', 'Tarık yahut Endülüs Fethi', ['Celaleddin Harzemşah', 'Gavè', 'Besa'], 'Tarık yahut Endülüs Fethi (ve onun içinde yer alan ünlü \'İbn-i Musa\' devam halkasıyla birlikte Endülüs dizisi), Hamit\'in en çok okunan tarihî oyunudur.'),
  ('Eski edebiyatın savunucusu olarak tanınmasına karşın Muallim Naci\'nin Batılı tarzda yazdığı ve Türk edebiyatında köy yaşamından söz eden ilk şiir kabul edilen manzumesi hangisidir?', 'Köylü Kızların Şarkısı', ['Kuzu', 'Dicle', 'Şam-ı Gariban'], 'Muallim Naci\'nin \'Tepeden nasıl iniyor bakın / Şu kızın nişanlısı şanlıdır\' dizeleriyle tanınan Köylü Kızların Şarkısı ilk köy şiiri sayılır.'),
  ('Muallim Naci\'nin şiir kitapları arasında yer alan \'Ateşpare, Şerare ve Fürûzan\' adlı eserlerin ortak biçim ve dil özelliği nedir?', 'Aruz veznini pürüzsüz bir Türkçe söyleyişle birleştirip hem klasik hem yeni nazım şekillerini barındırması', ['Tamamının yedili ve sekizli hece ölçüsüyle halk türküsü formunda söylenmiş olması', 'Serbest müstezat biçiminde noktalamasız ve bilinç akışı tekniğiyle dizilmiş bulunması', 'Yalnızca Farsça rubailerin satır altı kelime çevirilerinden meydana gelmesi'], 'Muallim Naci eski şiir zevkini sürdürürken Batılı çeviriler de yapmış ve aruzu konuşma Türkçesine en başarılı uygulayan geçiş şairlerinden olmuştur.'),
  ('Muallim Naci\'nin divan edebiyatı mazmunlarını ve klasik belagat terimlerini örnek beyitlerle açıkladığı, Recaizade\'nin Talim-i Edebiyat\'ına karşı geleneksel kuralları derlediği kitabı hangisidir?', 'Istılahat-ı Edebiyye', ['Takdir-i Elhan', 'Lügat-i Remzi', 'Mizanü\'l-Edeb'], 'Istılahat-ı Edebiyye, eski Türk edebiyatının edebî sanatlarını ve terimlerini sistemli biçimde öğreten temel başvuru eseridir.'),
  ('Mizancı Murat Bey\'in 1891\'de yayımlanan tek romanı Turfanda mı Yoksa Turfa mı\'da, Cezayir\'den İstanbul\'a gelerek bozulan bürokrasiyi düzeltmeye ve Anadolu\'da örnek okullar açmaya çalışan idealist doktor kimdir?', 'Mansur Bey', ['Rakım Efendi', 'Bihruz Bey', 'Ahmet Celal'], 'Otobiyografik izler taşıyan Turfanda mı Yoksa Turfa mı\'da Mansur Bey, Fransa\'da tıp okuyup İstanbul\'a gelen, dürüstlüğüyle yozlaşmış memurlarla çatışan idealist aydındır.'),
  ('Türk edebiyatının ilk kadın romancısı kabul edilen Fatma Aliye Hanım, 1892\'de kendi adıyla yayımladığı Muhadarat romanından önce Ahmet Mithat Efendi ile birlikte yazdığı Hayal ve Hakikat\'te hangi imzayı kullanmıştır?', 'Bir Kadın', ['Server Bedii', 'Raik Vecdi', 'Süha Senai'], 'Fatma Aliye Hanım önce Georges Ohnet\'den Meram çevirisinde \'Bir Kadın\', Ahmet Mithat\'la yazdığı Hayal ve Hakikat\'te \'Bir Kadın ve Ahmet Mithat\' imzasını kullanmış, Muhadarat\'ta kendi adını açıklamıştır.'),
  ('Fatma Aliye Hanım\'ın yoksul ve yetim bir genç kızın Darülmuallimat\'ı (Kız Öğretmen Okulu) bitirerek meslek sahibi olmasını ve ekonomik bağımsızlığını kazanmasını anlattığı romanı hangisidir?', 'Refet', ['Enin', 'Levayih-i Hayat', 'Taaddüd-i Zevcat'], '1898 tarihli Refet, annesi Binnaz\'ı kaybetmesine rağmen okuyup öğretmen olan Refet\'in azmini işleyerek Çalıkuşu\'ndaki Feride tipine öncülük etmiştir.'),
  ('Fatma Aliye Hanım\'ın Şam\'da tanıdığı bir müzik ustasının hayatından esinlenerek yazdığı ve mutsuz evliliğinin ardından İstanbul\'da ut dersleri vererek geçimini sağlayan Bedia\'yı anlattığı romanı hangisidir?', 'Udî', ['Sinekli Bakkal', 'Hüküm Gecesi', 'Kalp Ağrısı'], '1899 tarihli Udî romanında Fatma Aliye, kocası Mail\'in ihaneti sonrası boşanıp sanatıyla namuslu biçimde geçinen Bedia\'nın öyküsünü anlatır.'),
  ('Tanzimat ile Servetifünun arasındaki \'Ara Nesil\' döneminin en güçlü pozitivist düşünürü ve ilk natüralist eleştirmeni kabul edilen Beşir Fuat, 1885\'te yayımladığı hangi monografisiyle \'Hayaliyyun-Hakikiyyun\' (Romantizm-Realizm) tartışmasını başlatmıştır?', 'Victor Hugo', ['Emile Zola ve Deneysel Roman', 'Jean-Jacques Rousseau\'nun İtirafları', 'Shakespeare ve İngiliz Tiyatrosu'], 'Beşir Fuat, Victor Hugo\'nun ölümü üzerine yazdığı biyografik-eleştirel kitapta romantizmi (\'hayaliyyun\') eleştirip bilim ve deney temelli realizm/natüralizmi (\'hakikiyyun\') savunmuştur.'),
  ('Beşir Fuat\'ın Menemenlizade Mehmet Tahir ile girdiği kalem tartışmasında şiir ve duygu kavramlarına yaklaşımı nasıldır?', 'Gönül ve aşkın kalpte değil beyindeki fizyolojik süreçlerde doğduğunu söyleyerek sulu gözlü şairaneliğe karşı çıkar', ['Şiirin yalnızca ilahi ilhamla yazılan kutsal ve açıklanamaz bir sır olduğunu ileri sürer', 'Bilimsel terimlerin edebiyatın estetik büyüsünü bozduğu gerekçesiyle yasaklanmasını ister', 'Halk masallarındaki cin ve peri motiflerinin modern romanın tek kaynağı olduğunu savunur'], 'Katı bir pozitivist ve materyalist olan Beşir Fuat, yüreğin yalnızca kan pompalayan bir kas olduğunu belirterek romantik gözyaşı edebiyatını bilimsel açıdan eleştirmiştir.'),
  ('Beşir Fuat\'ın 1887 yılında otuz beş yaşındayken yaşamına son verme biçimi, onun pozitivist ve deneysel dünya görüşüyle nasıl bir paralellik taşımıştır?', 'Bileklerini kestikten sonra kan kaybederken hissettiği fizyolojik değişimleri dakika dakika kağıda not etmesiyle', ['Vasiyetnamesinde tüm kitaplarının yakılarak bilimin anlamsızlığının ilan edilmesini istemesiyle', 'Romantik roman kahramanlarına özenerek Çamlıca tepesinde veremli sevgilisinin mezarında zehir içmesiyle', 'İntihar mektubunu aruz vezniyle kaside biçiminde yazarak eski edebiyata bağlılığını bildirmesiyle'], 'Beşir Fuat annesinden geçen delilik korkusuyla intihar ederken ölüm anını bile bilimsel bir gözlem deneyine dönüştürüp Ahmet Mithat\'a mektup bırakmıştır.'),
  ('Ara Nesil şairlerinden şair Nigâr Hanım\'ın (Nigâr binti Osman) Salı toplantılarıyla edebiyatçıları konağında ağırlamasının yanı sıra, derin hüzün ve kadınsı duyarlılığı yansıttığı ilk şiir kitabı hangisidir?', 'Efsus', ['Şükûfezar', 'Makber', 'Piyale'], 'Nigâr Hanım iki kısımlık Efsus (Yazık!), Nîrân, Aks-i Seda ve Safahat-ı Kalb gibi eserleriyle Tanzimat sonrası bireysel lirizmin öncü kadın şairidir.'),
  ('Nabizade Nazım\'ın \'Seyyie-i Tesamüh, Hâlâ Güzel, Haspa ve Zavallı Kız\' gibi uzun hikâyelerinde Tanzimat I. Dönem anlatılarından ayrılan belirgin özellik nedir?', 'İstanbul\'un orta hâlli mahallelerini ve sıradan insanların psikolojisini gözlemci bir tutumla yansıtması', ['Olağanüstü cin, peri ve büyü olaylarını halk masalı üslubuyla yeniden kurgulaması', 'Haçlı Seferleri sırasındaki kale kuşatmalarını kahramanlık destanı biçiminde anlatması', 'Siyasal rejim tartışmalarını meclis tutanakları üzerinden diyaloglarla sunması'], 'Nabizade Nazım, hikâyelerinde realist-natüralist eğilimle gündelik yaşamı, aile içi ilişkileri ve ruhsal çatışmaları gözleme dayalı biçimde işlemiştir.'),
  ('Abdülhak Hamit Tarhan\'ın Londra ve Paris sefaret kâtiplikleri ile Bombay başkonsolosluğu görevleri onun edebî kişiliğini nasıl etkilemiştir?', 'Batı romantizmi, Hint doğası ve egzotik mekanların birleştiği kozmopolit bir imge dünyası kurmasını sağlamıştır', ['Anadolu kasabalarının yerel ağızlarını derleyerek halk öykücülüğüne yönelmesine yol açmıştır', 'Diplomatik yazışmaların resmi dili yüzünden şiirde her türlü hayal ve mecazı reddetmesine neden olmuştur', 'Avrupa edebiyatından soğuyarak yalnızca klasik Çağatay mesnevilerine nazire yazmasını tetiklemiştir'], 'Hamit\'in Paris (Sahra, Nesteren), Bombay/Hindistan (Duhter-i Hindu, Makber, Ölü, Hacle) ve Londra (Finten) yılları eserlerinin hem mekanlarını hem felsefi ufkunu belirlemiştir.'),
  ('Abdülhak Hamit\'in Makber mukaddimesinde \'En güzel, en büyük, en doğru şiir bir hakikat-i müdhişenin tazyiki altında hiçbir şey söyleyememektir\' sözüyle dile getirdiği poetik düşünce nedir?', 'Büyük trajediler ve ölüm acısı karşısında dilin ve sözcüklerin duyguları anlatmakta yetersiz kaldığı', ['Şairlerin toplumsal baskı dönemlerinde kalemlerini kırıp ticaretle uğraşmaları gerektiği', 'Kısa ve tek mısralık şiirlerin uzun mesnevilerden her zaman daha üstün sayıldığı', 'Sessiz pandomim sanatının tiyatro ve edebiyatın yerini bütünüyle alacağı'], 'Hamit, Makber önsözünde insanı ezen korkunç gerçek (ölüm) karşısında dilsiz kalmanın asıl şiir olduğunu, kendisinin ise bu acıyı dindirmek için feryat ettiğini belirtir.'),
  ('Nabizade Nazım\'ın Zehra romanında Boğaziçi, tulumbacı kahveleri ve orta oyunu sahnelerini uzun uzadıya betimlemesi natüralizm açısından nasıl değerlendirilir?', 'İnsan karakterini şekillendiren toplumsal çevreyi belgesel bir titizlikle saptama çabası olarak', ['Sayfa sayısını artırarak gazeteden daha fazla tefrika ücreti alma kurnazlığı olarak', 'Turist rehberi hazırlamak amacıyla İstanbul\'un gezilecek yerlerini listeleme girişimi olarak', 'Divan edebiyatındaki şehrengiz geleneğini hece vezniyle diriltme denemesi olarak'], 'Natüralist anlayışta \'soyaçekim ve çevre\' insanı belirlediği için Nabizade Nazım İstanbul\'un mahalle hayatını, tulumbacıları ve eğlencelerini gözlem notlarıyla romana sokmuştur.'),
  ('Abdülhak Hamit\'in Londra\'daki Hyde Park\'tan ve İskoç doğasından izlenimlerle yazdığı \'Kürsi-i İstiğrak\' ve \'Külbe-i İştiyak\' şiirlerinde doğaya bakışı nasıldır?', 'Tabiatı Tanrı\'nın kudretinin tecelli ettiği sonsuz ve panteist çağrışımlı bir tefekkür alanı olarak görür', ['Doğayı yalnızca tarımsal üretim ve maden işletmeciliği açısından ekonomik bir kaynak sayar', 'Divan şiirindeki mazmunlara sadık kalarak doğayı soyut bir gül bahçesi şemasına indirger', 'Doğa manzaralarını insan ruhuna düşman, korkutucu ve kaçılması gereken bir cehennem gibi çizer'], 'Hamit bu iki ünlü şiirinde (Hayret Kürsüsü ve Özlem Kulübesi) doğa karşısında vecde gelerek varoluşu ve Yaratıcı\'yı derin bir lirizmle düşünür.'),
  ('Tanzimat II. Dönem\'de \'mensur şiir\' türünün doğuşuna zemin hazırlayan ve Recaizade ile Sezai\'den Halit Ziya\'ya uzanan üslup arayışı nasıl tanımlanabilir?', 'Düzyazıda iç uyak, ünlem, devrik söyleyiş ve lirik imgeler kullanarak şiirsel bir nesir kurma eğilimi', ['Gazete haberlerini telgraf cümleleriyle hiçbir sıfat kullanmadan kuru biçimde aktarma yöntemi', 'Resmi devlet fermanlarındaki dua ve lakap zincirlerini roman diyaloglarına taşıma alışkanlığı', 'Halk tekerlemelerini bilmece kalıplarıyla birleştirerek çocuk masalları oluşturma çabası'], 'Hamit\'in Makber mukaddimesi, Recaizade\'nin Pejmürde ve Takdir-i Elhan\'daki lirik parçaları ile Sezai\'nin nesirleri, Halit Ziya\'nın Mezardan Sesler\'ine giden mensur şiir yolunu açmıştır.'),
  ('Araba Sevdası\'nda Bihruz Bey\'in Fransızca hocası Mösyö Pierre\'in karakter özelliği nedir?', 'Öğrencisinin cehaletini ve gösteriş merakını dalkavuklukla sömürüp ondan sürekli para koparan çıkarcı bir tiptir', ['Bihruz Bey\'i israftan vazgeçirmek için babasının borçlarını kendi cebinden ödeyen fedakâr bir dosttur', 'Osmanlı tarihine hayran olup Türkçe sözlük hazırlayan dürüst bir şarkiyat bilginidir', 'Periveş\'in gerçek kimliğini ilk günden Bihruz Bey\'e açıklayarak onu uyaran ahlaklı bir eğitmendir'], 'Altmış beş yaşındaki paragöz Mösyö Pierre, Bihruz Bey\'e hiçbir şey öğretmediği hâlde onu pohpohlayarak maaş ve hediyeler koparır.'),
  ('Fatma Aliye Hanım\'ın Avrupalı kadın gezginlerin Osmanlı haremi hakkındaki yanlış ve oryantalist önyargılarını düzeltmek amacıyla diyalog biçiminde yazdığı ve Fransızcaya da çevrilen eseri hangisidir?', 'Nisvan-ı İslam', ['Kadınlarımız', 'Bize Göre', 'Anadolu Notları'], 'Fatma Aliye Hanım\'ın 1892 tarihli Nisvan-ı İslam (İslam Kadınları) adlı eseri, konağı ziyaret eden Avrupalı hanımlarla yapılan sohbetler üzerinden Müslüman kadının konumunu anlatır.'),
  ('Nabizade Nazım\'ın genç yaşta kemik vereminden ölmeden önce hem şiir (Heves Ettim) hem de fizik, astronomi ve cebir üzerine popüler bilim kitapçıkları yayımlaması neyi gösterir?', 'Ara Nesil aydınlarındaki pozitivist fen merakı ile edebî yaratıcılığın bir arada yürüdüğünü', ['Askeri okullarda edebiyat okumanın yasak olması yüzünden şiirlerini fen kitabı kapağıyla gizlediğini', 'Edebiyattan hiç gelir elde edemediği için geçimini yalnızca okul müfredatı satarak sağladığını', 'Şiirde vezin ve kafiyeyi matematik denklemleriyle hesaplayan yeni bir akım kurduğunu'], 'Beşir Fuat gibi asker kökenli olan Nabizade Nazım, pozitivist bilim ilgisini natüralist roman ve öykü tekniğine doğrudan yansıtmıştır.'),
  ('Araba Sevdası\'nın sonunda Ramazan akşamı Şehzadebaşı\'nda Periveş\'e tıpatıp benzeyen bir kadın gören Bihruz Bey\'in yaşadığı sarsıcı aydınlanma nedir?', 'Öldüğünü sanıp aylarca yasını tuttuğu kadının aslında Periveş\'in bizzat kendisi olduğunu ve kendisiyle alay ettiğini öğrenmesi', ['Periveş\'in ikiz kardeşinin kendisine büyük bir miras bıraktığını noter belgesiyle haber alması', 'Keşfi Bey\'in Periveş ile gizlice evlenip Fransa\'ya yerleşmeye hazırlandığını görmesi', 'Lando arabasını haczeden araba satıcısının Periveş\'in öz ağabeyi olduğunun anlaşılması'], 'Şehzadebaşı\'nda Periveş ve arkadaşı Çengi Hanım\'la karşılaşan Bihruz, önce kadını Periveş\'in ablası sanır; gerçeği ve alaya alındığını anlayınca hayal dünyası tamamen yıkılır.'),
  ('Nabizade Nazım\'ın Karabibik adlı eserinde köylülerin \'sarıca, kâhya, öküz, dönüm, sıtma\' gibi somut dertlerle uğraşırken dilde yerel Kaş ağzının kullanılması, önceki dönem eserleriyle karşılaştırıldığında neyi değiştirmiştir?', 'Edebiyatın ilk kez İstanbul aydınlarının konak dışına çıkarak Anadolu köylüsünü romantik süslemeden uzak işlemesini sağlamıştır', ['Köy hayatını Sahra\'daki gibi çoban kavalı ve kaygısız bir cennet tablosu olarak resmetmiştir', 'Yazarların İstanbul Türkçesini tamamen terk edip tüm romanları Antalya ağzıyla yazmasına yol açmıştır', 'Köylülerin toprak ağalarına karşı silahlı ayaklanma başlatmasını öğütleyen politik bir bildiriye dönüşmüştür'], 'Hamit\'in Sahra\'sı ve Naci\'nin Köylü Kızların Şarkısı köyü uzaktan ve idealize ederek anlatırken, Karabibik sıtması, borcu ve kaba diliyle gerçek köyü edebiyata sokmuştur.'),
  ('Tanzimat II. Dönem\'de gazetenin önemini yitirip onun yerini \'mecmua\'ların (Hazine-i Evrak, Mir\'at-ı Âlem, Güneş, Mirsad, Servet-i Fünun vb.) almasının edebî sonucu ne olmuştur?', 'Günlük politik tartışmalar yerine edebî-felsefi incelemelerin, şiirlerin ve sanat polemiklerinin öne çıkması', ['Roman tefrikalarının tamamen bırakılıp yalnızca borsa ve gümrük cetvellerinin yayımlanması', 'Dergilerin parasız dağıtılması sayesinde halk edebiyatı âşıklarının matbaalara hâkim olması', 'Yazarların telif hakkı alamadığı için edebiyatı bırakıp memurluğa geçmesi'], 'Sansür nedeniyle siyasal gazetecilik daralınca Hazine-i Evrak, Güneş, Mirsad ve nihayet Servet-i Fünun gibi sanat-edebiyat dergileri edebî hayatın merkezi hâline gelmiştir.'),
  ('II. Abdülhamit döneminin baskıcı atmosferinden bunalan Servetifünun sanatçılarının topluca İstanbul\'dan uzaklaşıp özgürce yaşamak için kurdukları ortak kaçış hayali hangi iki mekanla simgeleşmiştir?', 'Yeni Zelanda ve Manisa\'nın Sarıçam çiftliği', ['İsviçre Alpleri ve Bursa\'nın Çekirge sırtları', 'Mısır\'ın İskenderiye kıyıları ve Büyükada çamlıkları', 'Güney Fransa sahilleri ve Antalya\'nın Kaş yaylaları'], 'Servetifünuncular önce Okyanusya\'daki Yeni Zelanda\'ya gitmeyi düşlemiş, bu gerçekleşmeyince Hüseyin Kazım Kadri\'nin Manisa\'daki Sarıçam köyünde bulunan çiftliğine çekilmeyi planlamışlardır.'),
  ('Tevfik Fikret\'in \'Yeşil Yurt\' adlı şiiri, Servetifünun kuşağının hangi psikolojik eğilimini somutlaştıran tipik bir örnektir?', 'Gerçek dünyadaki baskıdan doğaya ve ütopik bir kır yuvasına sığınma arzusunu', ['Anadolu köylüsünü tarımsal kalkınma seferberliğine çağıran toplumcu bilinci', 'Eski divan bahçelerindeki lale ve bülbül mazmunlarını yeniden diriltme çabasını', 'Sanayileşen kentlerin fabrika dumanlarını öven fütürist ilerleme heyecanını'], 'Hüseyin Kazım\'ın Manisa\'daki çiftliği hayaliyle yazılan Yeşil Yurt, Servetifünun\'un \'hayal-hakikat çatışması\' ve doğaya kaçış temasını yansıtır.'),
  ('Servetifünun şairlerinin \'saat-i semen-fâm\' (yasemin renkli saatler), \'hande-i muzlim\' (karanlık gülüş) ve \'lerze-i rûşen\' (aydınlık titreyiş) gibi alışılmamış bağdaştırmalar kurmalarının temel estetik nedeni nedir?', 'Duyular arası aktarmalarla ince ve bireysel ruh hâllerini sezdirme arayışı', ['Medrese ulemasının Arapça belagat sınavlarındaki kurallara bağlılık gösterme isteği', 'Halkın günlük konuşma dilindeki deyimleri aruz kalıplarına yerleştirme kaygısı', 'Resmî yazışmalardaki protokol unvanlarını şiir diline eksiksiz taşıma zorunluluğu'], 'Fransız sembolist ve parnasyenlerinden etkilenen Servetifünuncular, var olan sözcüklerle anlatılamayan izlenimleri sinestezi (duyu aktarması) ve özgün Farsça tamlamalarla ifade etmiştir.'),
  ('Tevfik Fikret\'in Servetifünun dönemi içinde kaleme aldığı hâlde bireysel melankoliden sıyrılıp yoksul insanların geçim dramına eğildiği manzum hikâyeleri arasında aşağıdakilerden hangisi yer alır?', 'Balıkçılar, Hasta Çocuk, Nesrin ve Ramazan Sadakası', ['Elhan-ı Şita, Yakazat-ı Leyliye, Makamat ve Tamat', 'Küfe, Seyfi Baba, Mahalle Kahvesi ve Kocakarı ile Ömer', 'Cenge Giderken, Anadolu, Bırak Beni Haykırayım ve Kesildi mi Ellerin'], 'Tevfik Fikret daha Servetifünun yıllarındayken Balıkçılar (\'Bugün açız yine evlatlarım\'), Hasta Çocuk, Verin Zavallılara ve Ramazan Sadakası ile sosyal merhamet temalı manzum öyküler yazmıştır.'),
  ('Tevfik Fikret\'in \'Balıkçılar\' adlı manzum hikâyesinde geçim sıkıntısının yarattığı trajedi hangi olay etrafında somutlaştırılır?', 'Aç kalan ailesini doyurmak için fırtınalı denize açılan ihtiyar balıkçının delinen teknesiyle sefalete yenik düşmesi', ['Zengin bir yalı sahibinin Boğaz\'daki balık dalyanlarını satın alarak mahalleliyi göçe zorlaması', 'Yabancı buharlı gemilerin Haliç\'teki küçük sandallara çarparak tüm tayfaları sulara gömmesi', 'Balık pazarı esnafının belediye zabıtalarıyla vergi yüzünden girdiği kavgada dükkânların yıkılması'], 'Balıkçılar manzumesinde oğlu denizde boğulmuş yaşlı balıkçı ve hasta karısı evde ekmek kalmayınca fırtınaya rağmen denize açılmak zorunda kalır.'),
  ('Tevfik Fikret\'in II. Meşrutiyet\'in ilanından hemen sonra 1908\'de Sis şiirindeki karamsarlığını geri alarak İstanbul\'dan özür dilediği ve umudu selamladığı şiiri hangisidir?', 'Rücu', ['Doksan Beşe Doğru', 'Hân-ı Yağma', 'Tarih-i Kadim'], '1908 Meşrutiyet\'inin yarattığı özgürlük sevinciyle Fikret, \'Hayır, hayır, sana râci değil bu tel\'înât\' diyerek Sis\'ten dönüş anlamına gelen Rücu şiirini yazmıştır.'),
  ('Tevfik Fikret, Hüseyin Cahit Yalçın ve Hüseyin Kazım Kadri\'nin 1908\'de birlikte çıkardıkları Tanin gazetesinden Fikret\'in kısa sürede ayrılmasının temel nedeni nedir?', 'Gazetenin İttihat ve Terakki Fırkasının partizan yayın organına dönüşmesine ilkeli biçimde karşı çıkması', ['Tanin matbaasının 31 Mart Olayı\'nda yıkılmasından sonra gazetenin bir daha basılamaması', 'Hüseyin Cahit\'in hece ölçüsünü zorunlu kılıp aruzla yazılmış şiirleri yayımlamayı reddetmesi', 'Fikret\'in Maarif Nazırlığı görevini kabul ederek kabineye bakan sıfatıyla katılması'], 'Ödünsüz ve bağımsız kişiliğiyle tanınan Fikret, Hüseyin Cahit\'in Tanin\'i İttihat ve Terakki\'nin sözcüsü yapması üzerine gazeteden ayrılmıştır.'),
  ('1912 yılında İttihat ve Terakki\'nin Meclis-i Mebusan\'ı feshetmesini II. Abdülhamit\'in 1877\'de (Rumi 1293/1295 sürecinde) meclisi kapatmasına benzeterek eleştiren Tevfik Fikret şiiri hangisidir?', 'Doksan Beşe Doğru', ['Bir Lahza-i Teahhur', 'Rübabın Cevabı', 'Haluk\'un Vedası'], 'Fikret, \'Bir devr-i şeâmet: Yine çiğnendi yeminler!\' dizesiyle başlayan Doksan Beşe Doğru\'da İttihatçıların meclisi kapatmasını eski istibdada dönüş saymıştır.'),
  ('Tevfik Fikret\'in 1905 yılında Ermeni komitecilerin II. Abdülhamit\'e Cuma selamlığında düzenlediği bombalı suikast girişiminde padişahın birkaç dakikalık gecikmeyle kurtulmasına hayıflanarak yazdığı şiir hangisidir?', 'Bir Lahza-i Teahhur', ['Tarih-i Kadim\'e Zeyl', 'Mâi Deniz', 'Yağmur'], 'Fikret \'Ey şanlı avcı, dâmını bihûde kurmadın!\' dizesinin yer aldığı Bir Lahza-i Teahhur (Bir Anlık Gecikme) şiirinde suikastın başarısız olmasına üzüntüsünü dile getirmiştir.'),
  ('Cenap Şahabettin\'in gençlik dönemi şiirlerini 1887\'de topladığı tek basılı şiir kitabı aşağıdakilerden hangisidir?', 'Tamat', ['Evrak-ı Leyal', 'Gizli Figanlar', 'Fani Teselliler'], 'Cenap Şahabettin sağlığında olgunluk şiirlerini \'Evrak-ı Leyal\' adıyla bastırmak istemişse de yayımlayamamış; yalnızca gençlik şiirlerini içeren Tamat basılmıştır.'),
  ('Cenap Şahabettin\'in gece vakti uzak bir odadan süzülen piyano seslerini ve yarattığı hüzünlü hayalleri aruzun müzikalitesiyle işlediği tanınmış şiiri hangisidir?', 'Yakazat-ı Leyliye', ['Göl Saatleri', 'Leyal-i Girizan', 'Kürsi-i İstiğrak'], 'Yakazat-ı Leyliye (Gece Uyanıklıkları), Elhan-ı Şita ile birlikte Cenap Şahabettin\'in sembolizm ve parnasizm sentezini gösteren en ünlü şiiridir.'),
  ('Cenap Şahabettin\'in Birinci Dünya Savaşı yıllarında Bağdat ve çevresine yaptığı seyahati anlattığı eseri ile Avrupa gezilerini topladığı kitabı hangi seçenekte birlikte verilmiştir?', 'Afak-ı Irak ve Avrupa Mektupları', ['Firak-ı Irak ve Berlin Mektupları', 'Mir\'at-ı Memalik ve Londra Sergisi', 'Suriye Mektupları ve Anadolu Notları'], 'Cenap Şahabettin\'in Hac Yolunda dışındaki başlıca gezi yazıları Afak-ı Irak (Irak Ufukları), Avrupa Mektupları ve Suriye Mektupları\'dır.'),
  ('Cenap Şahabettin\'in makale ve denemelerini topladığı \'Evrak-ı Eyyam\' ile \'Nesr-i Harp, Nesr-i Sulh\' dışındaki iki tiyatro oyunu aşağıdakilerden hangisidir?', 'Yalan ve Körebe', ['Pençe ve Cidal', 'Kâbus ve Füruzan', 'Çürük Temel ve Yamalar'], 'Cenap Şahabettin, mütareke ve evlilik komedisi konularına değinen Yalan ve Körebe (ve küçük piyesi Küçük Beyler) adlı sahne eserlerini yazmıştır.'),
  ('Servetifünun şairleri arasında \'İbrahim Cehdi\' takma adıyla yayımladığı \'Gizli Figanlar\' kitabından sonra 1908\'in ardından Namık Kemal çizgisinde gür bir vatan şairine dönüşen sanatçı kimdir?', 'Süleyman Nazif', ['Hüseyin Siret Özsever', 'Celal Sahir Erozan', 'Ahmet Reşit Rey'], 'Süleyman Nazif istibdat yıllarında Mısır\'da İbrahim Cehdi adıyla Gizli Figanlar\'ı bastırmış; Balkan ve I. Dünya Savaşları\'nda ise vatan ve millet temalı hamasi eserler vermiştir.'),
  ('İtilaf Devletleri komutanı Fransız General Franchet d\'Espèrey\'in 8 Şubat 1919\'da beyaz atıyla İstanbul\'a gösterişli girişi üzerine Süleyman Nazif\'in Hadisat gazetesinde yayımladığı ve Malta\'ya sürülmesine yol açan ünlü makale hangisidir?', 'Kara Bir Gün', ['İzmir\'e Doğru', 'Vurun Kahpeye', 'Mütareke Karanlığı'], 'Süleyman Nazif \'Kara Bir Gün\' başlıklı yazısıyla işgal komutanının küstahlığını protesto etmiş; idamdan son anda kurtulup İngilizlerce Malta\'ya sürülmüştür.'),
  ('Süleyman Nazif\'in Malta sürgününde vatan hasretiyle yazdığı \'Dâüssıla\' şiirini içeren kitabı ile Bağdat\'ın elden çıkışı üzerine kaleme aldığı eseri hangileridir?', 'Malta Geceleri ve Firak-ı Irak', ['Limni Mektupları ve Afak-ı Irak', 'Batarya ile Ateş ve Elhan-ı Vatan', 'Sürgün Hatıraları ve Hac Yolunda'], '\'Bu şeb de cûşiş-i yâdınla ağladım durdum\' mısraıyla ünlü Dâüssıla şiiri Malta Geceleri\'nde; Irak cephesinin kaybına yakılan ağıtlar ise Firak-ı Irak\'ta yer alır.'),
  ('Fransız eleştirmen Hippolyte Taine\'in \'ırk, çevre ve zaman\' kuramını benimseyerek Servetifünun döneminde nesnel ve bilimsel Batı eleştirisini tanıtan \'Hayat ve Kitaplar\' yazarı kimdir?', 'Ahmet Şuayp', ['Raif Necdet Kestelli', 'Hüseyin Suat Yalçın', 'Ahmet Hikmet Müftüoğlu'], 'Hukukçu ve eleştirmen Ahmet Şuayp, Flaubert, Taine, Mommsen ve Niebuhr üzerine incelemelerini içeren Hayat ve Kitaplar eseriyle sadece eleştiri türüne odaklanan tek Servetifünuncudur.'),
  ('Servetifünun\'un \'ikinci Hamit\' olma iddiasıyla romantik-lirik şiirler yazan (\'Fani Teselliler\', \'Temasil\') ve daha sonra Fecriati topluluğunun isim babası ve ilk başkanı seçilen şair kimdir?', 'Faik Ali Ozansoy', ['Celal Sahir Erozan', 'Tahsin Nahit', 'Emin Bülent Serdaroğlu'], 'Süleyman Nazif\'in kardeşi olan Faik Ali Ozansoy, Servetifünun\'da yetişmiş, 1909\'da gençlerin kurduğu Fecriati\'ye adını vermiş ve Payitahtın Kapısında gibi manzum oyunlar yazmıştır.'),
  ('Servetifünun\'da \'Beyaz Gölgeler\', \'Buhran\' ve \'Siyah Kitap\' adlı eserleriyle \'kadın ve aşk şairi\' olarak tanınan, daha sonra Fecriati ve Millî Edebiyat saflarına katılan şair kimdir?', 'Celal Sahir Erozan', ['Hüseyin Siret Özsever', 'Süleyman Nesip', 'İsmail Safa'], 'Celal Sahir Erozan edebiyat hayatına Servetifünun\'da başlamış, Fecriati bildirisini imzalamış, ardından Yeni Lisan hareketini benimseyerek Türkçü çizgiye geçmiştir.'),
  ('Ahmet Hikmet Müftüoğlu\'nun Servetifünun döneminde ağır ve süslü bir üslupla yazdığı öykü ve mensur şiirlerini topladığı 1901 tarihli kitabı hangisidir?', 'Haristan ve Gülistan', ['Çağlayanlar', 'Gönül Hanım', 'Hayat-ı Muhayyel'], 'Ahmet Hikmet Müftüoğlu edebiyata Servetifünun\'da ağdalı dille yazdığı Haristan ve Gülistan ile başlamış; 1908 sonrası Türkçülük akımına geçerek yalın dilli Çağlayanlar ve Gönül Hanım\'ı yazmıştır.'),
  ('Ahmet Hikmet Müftüoğlu\'nun Servetifünun dilinden Millî Edebiyat\'ın duru Türkçesine geçişini simgeleyen \'Üzümcü\' ve \'Alparslan Masalı\' gibi milli-destansı öyküleri hangi eserinde yer alır?', 'Çağlayanlar', ['Haristan ve Gülistan', 'Kızıl Elma', 'Milli Savaş Hikâyeleri'], '1922\'de yayımlanan Çağlayanlar, Türk kültürünü, Anadolu insanının çilesini (\'Üzümcü\') ve ulusal gururu işleyen on sekiz hikâyeden oluşur.'),
  ('Ahmet Hikmet Müftüoğlu\'nun Birinci Dünya Savaşı\'nda Kafkas cephesinde esir düşen Üsteğmen Mehmet Tolun\'un Tatar kızı Gönül Hanım\'la Orhun Yazıtları\'nı bulmak üzere çıktığı yolculuğu anlatan romanı hangisidir?', 'Gönül Hanım', ['Yeni Turan', 'Aydemir', 'Tatarcık'], '1920\'de Tasvir-i Efkâr\'da tefrika edilen Gönül Hanım, Turancılık idealini ve Göktürk Abideleri\'ne yapılan bilimsel-milli seyahati işleyen tezli bir romandır.'),
  ('Servetifünun dergisinin sahibi ve başyazarı Ahmet İhsan Tokgöz\'ün 1890-1914 yılları arasındaki basın hayatını, sansür memurlarını ve Edebiyat-ı Cedidecilerin dergi odasındaki dostluklarını anlattığı anı eseri hangisidir?', 'Matbuat Hatıralarım', ['Kırk Yıl ve Saray ve Ötesi', 'Edebiyat Anıları ve Siyasal Anılar', 'Gençlik ve Edebiyat Hatıraları'], 'Jules Verne çevirileriyle de tanınan Ahmet İhsan Tokgöz, iki ciltlik Matbuat Hatıralarım kitabında Servet-i Fünun dergisinin perde arkasını belgelemiştir.'),
  ('Servetifünun şiirinde aruz vezninin kullanım biçimi önceki dönemlerle karşılaştırıldığında hangi yenilik dikkat çeker?', 'Konunun duygusal akışına göre tek bir şiir içinde bile farklı aruz kalıplarının müzikal uyumla seçilmesi', ['Yalnızca kaside ve gazel kalıplarının korunup diğer tüm aruz bahirlerinin kullanımdan kaldırılması', 'Aruz kusurlarını gizlemek amacıyla her mısra sonuna Türkçe ekler yerine Farsça edatlar getirilmesi', 'Vezin zorunluluğunun tamamen reddedilerek hece sayısı belirsiz serbest şiire geçilmesi'], 'Fikret ve Cenap, aruz kalıplarının ses değerleriyle şiirin teması arasında bağ kurmuş (örneğin Elhan-ı Şita\'da karın hızına göre üç ayrı kalıp kullanılması), \'konuya göre vezin\' ilkesini geliştirmişlerdir.'),
  ('Tevfik Fikret\'in \'Promete\' adlı şiirinde Yunan mitolojisinden aldığı figür aracılığıyla gençliğe verdiği mesaj aşağıdakilerden hangisidir?', 'Her sabah ciğerini kemiren cehalet kartalına rağmen gökten elektrik ve bilim ateşini çalma azmini taşımak', ['Batı medeniyetinin kibrine kapılmadan geleneksel el sanatlarını ve kanaatkâr yaşamı korumak', 'Tanrılara baş kaldıran mitolojik kahramanların uğradığı gazaptan ibret alarak kadere boyun eğmek', 'Savaş meydanlarında kaybedilen toprakları geri almak için orduda gönüllü süvari yazılmak'], '\'Kalbinde her dakika şu ulvî tahassürün / Minkâr-ı âteşînini duy, dâimâ düşün!\' diyen Fikret, Promete\'yi uygarlık ve fen ışığını ülkesine getirecek gencin sembolü yapar.'),
  ('Tevfik Fikret\'in 1911 Trablusgarp Savaşı ve İttihat-Terakki baskıları ortamında vatanın uğradığı felaketleri gençliğin ağzından sorguladığı son dönem şiir kitabı hangisidir?', 'Rübabın Cevabı', ['Rübab-ı Şikeste', 'Haluk\'un Defteri', 'Şermin'], '1911\'de yayımlanan Rübabın Cevabı, vatanın parçalanışı ve hürriyetin yeniden kısıtlanması karşısında Fikret\'in toplumsal ıstırabını yansıtır.'),
  ('Servetifünun şairlerinin doğa betimlemelerinde \'kartpostal manzarası\' veya \'tablo altı şiir\' yöntemine başvurmalarının altında yatan pratik ve estetik etken nedir?', 'Sansür yüzünden toplumsal konulara girememeleri ve dergide Avrupa\'dan gelen klişe doğa resimlerine uygun şiir yazmaları', ['Fotoğraf makinesinin Osmanlı topraklarına girişinin yasak olması nedeniyle manzaraları sözle belgeleme görevi', 'Köylü okurlara mevsimlik ekim ve hasat zamanlarını resimli takvimlerle öğretme zorunluluğu', 'Divan şiirindeki bahariyye ve şitaiyye kasidelerini padişahlara sunarak caize alma geleneği'], 'Ahmet İhsan\'ın Servet-i Fünun dergisi Avrupa\'dan getirtilen gravür ve klişe resimlerle basıldığı için Fikret ve arkadaşları bu tablolara bakarak \'pitoresk\' şiirler kaleme almışlardır.'),
  ('Süleyman Nazif\'in Birinci Dünya Savaşı yıllarında ordunun kahramanlığını ve vatan savunmasını hem manzum hem mensur parçalarla yücelttiği 1917 tarihli eseri hangisidir?', 'Batarya ile Ateş', ['Ordunun Destanı', 'Eğil Dağlar', 'Cenk Ufukları'], 'Süleyman Nazif\'in Batarya ile Ateş adlı kitabı, savaş yıllarında vatan sevgisini gür ve sanatlı bir nesir-nazım üslubuyla dile getiren en tanınmış eserlerindendir.'),
  ('Cenap Şahabettin\'in nesir üslubu değerlendirildiğinde Tevfik Fikret veya Halit Ziya\'nın düzyazılarından ayrılan en belirgin yönü nedir?', 'Ciddi konuları bile zekice buluşlar, ince alay, kelime oyunları ve şaşırtıcı benzetmelerle nüktedan biçimde işlemesi', ['Hiçbir sıfat ve tamlama kullanmadan telgraf kısalığında kuru ve öğretici cümleler kurması', 'Anadolu ağızlarındaki yerel deyimleri ve atasözlerini olduğu gibi makalelerine taşıması', 'Yalnızca trajik ölüm sahnelerini ağlamaklı ve karamsar bir ağıt tonuyla betimlemesi'], 'Şiirlerinde melankolik ve sembolist olan Cenap Şahabettin, Hac Yolunda, Evrak-ı Eyyam ve Tiryaki Sözleri gibi nesirlerinde son derece kıvrak, ironik ve nüktedan bir zekâ yazarıdır.'),
  ('Tevfik Fikret\'in 1894 İstanbul depreminin yıkımını anlattığı \'Zelzele\', yaşlı bir kadının açlığını işlediği \'Verin Zavallılara\' ve alkolün aile yıkımını gösterdiği \'Sarhoş\' şiirleri hangi ortak çizgide buluşur?', 'Bireysel sanat dönemindeyken bile toplumsal acılara ve merhamet duygusuna duyarlı kalması', ['Natüralizm akımının soyaçekim kuramını klinik tıp raporlarıyla kanıtlama girişimi', 'İstibdat yönetiminin belediye hizmetlerindeki başarısını öven resmi kaside geleneği', 'Halk edebiyatındaki destan şairlerinin on birli hece ölçüsüyle afetleri anlatma tarzı'], 'Fikret, Servetifünun\'un bireysel döneminde dahi merhamet ve insani duyarlılıkla yoksulluk, hastalık ve felaket tablolarını realist manzum hikâyelere dönüştürmüştür.'),
  ('Servetifünun nesrinde ve şiirinde sıkça karşılaşılan \'kesik cümle\' (eksiltili cümle), \'evet...\', \'ah!\' gibi ünlemler ve ara sözler üsluba hangi işlevi kazandırmıştır?', 'Heyecanlı, kırılgan ve dalgalı ruh hâllerini konuşma ritmine benzer izlenimci bir akışla yansıtmayı', ['Resmî mahkeme tutanaklarındaki kesin ve tartışmasız hüküm dilini edebiyata yerleştirmeyi', 'Okurun metni ezberlemesini kolaylaştıracak secili divan nesri kalıplarını güçlendirmeyi', 'Dizgi hatalarını gizleyerek dergi sayfalarında görsel boşluklar yaratmayı'], 'Fransız Goncourt Kardeşler\'in \'artiste\' (sanatkârane/izlenimci) üslubundan etkilenen Servetifünuncular, uzun tamlamalı cümlelerin arasına üç noktalı kesik cümleler ve ünlemler serpiştirmiştir.'),
  ('Hüseyin Cahit Yalçın\'ın 1901\'de Servet-i Fünun\'un kapanmasına yol açan \'Edebiyat ve Hukuk\' makalesinde sansür kurulunu ve sarayı alarma geçiren asıl ifade neydi?', '1789 Fransız İhtilali\'nin gerçekleştiği günden ve monarşinin yıkılışından söz eden tarihsel gönderme', ['Osmanlı donanmasının Haliç\'te çürümeye terk edildiğini rakamlarla açıklayan askeri rapor', 'Yabancı bankaların Düyun-ı Umumiye aracılığıyla tütün gelirlerine el koymasını eleştiren paragraf', 'Arap alfabesinin okuma yazmayı zorlaştırdığını belirterek Latin harflerini öneren cümle'], 'II. Abdülhamit sansüründe \'ihtilal, cumhuriyet, grev, suikast\' gibi kelimeler kesinlikle yasaktı; makalede Fransız İhtilali ifadesinin geçmesi jurnal edilince dergi kapatıldı.'),
  ('Tevfik Fikret\'in \'Millet Şarkısı\'nda geçen \'Zulmün topu var, güllesi var, kal\'ası varsa / Hakkın da bükülmez kolu, dönmez yüzü vardır!\' beyti şairin hangi dönüm noktasının ürünüdür?', '1908 II. Meşrutiyet\'in ilanından hemen önce İttihatçı subayların hürriyet mücadelesine verdiği desteğin', ['1897 Türk-Yunan Savaşı\'nda Dömeke Meydan Muharebesi\'nin kazanılması üzerine duyulan sevincin', '1919 İzmir\'in işgali sonrasında Sultanahmet Mitingi\'nde halka okunan protesto bildirisinin', '1876 Birinci Meşrutiyet\'in ilanında Namık Kemal ile birlikte Kanun-ı Esasi komisyonunda çalışmasının'], 'Tevfik Fikret 1908 Temmuz\'unda Meşrutiyet ilan edilirken kaleme aldığı Millet Şarkısı ile hürriyet ve adalet heyecanının marşını yazmıştır.'),
  ('Cenap Şahabettin\'in \'Terâne-i Mehtâb\' ve \'Temâşâ-yı Leyâl\' gibi şiirlerinde doğayı gece, mehtap, gölge ve sonbahar saatlerinde betimlemesinin sembolizmle ilişkisi nedir?', 'Alacakaranlığın belirsizliğinde dış nesnelerin netliğini silerek ruhsal çağrışımlara zemin hazırlaması', ['Elektrik aydınlatmasının yaygınlaşmadığı İstanbul sokaklarındaki güvenlik sorununa dikkat çekmesi', 'Astronomi bilimine duyduğu ilgi nedeniyle yıldız kümelerinin konumlarını haritalandırması', 'Güneş ışığının cilt hastalıklarına zarar verdiği yönündeki tıbbi bilgisini şiire aktarması'], 'Sembolist estetikte öğle güneşi nesneleri keskin ve çıplak gösterdiği için hayali öldürür; mehtap, akşam ve sonbahar ise melankolik çağrışımları besler.'),
  ('Tevfik Fikret\'in küçük damla seslerini kısa hecelerle ve su şırıltısını çağrıştıran ünsüz tekrarlarıyla duyurduğu \'Küçük, muttarid, muhteriz darbeler / Kafeslerde, camlarda pür-ihtizâz\' dizeleri hangi şiirine aittir?', 'Yağmur', ['Elhan-ı Şita', 'Mâi Deniz', 'Balıkçılar'], 'Tevfik Fikret\'in \'Yağmur\' şiiri, Cenap\'ın Elhan-ı Şita\'sında karın yağışını duyurmasına benzer biçimde yağmur damlalarının camlardaki tıkırtısını aruz ve aliterasyonla yansıtır.'),
  ('Servetifünun\'un eleştiri anlayışında Muallim Naci-Recaizade döneminin \'kelime ve vezin hatası avcılığına\' kıyasla gerçekleşen en önemli sıçrama nedir?', 'Eseri yazarın psikolojisi, yaşadığı çevre ve estetik bütünlük içinde çözümleyen Batılı eleştiriye geçilmesi', ['Eleştiri yazılarının tamamının manzum hicviyeler biçiminde kafiyeli olarak kaleme alınması', 'Yalnızca divan şairlerinin hayat hikâyelerini tezkire geleneğine göre sıralamakla yetinilmesi', 'Bir eserin değerini yalnızca satış rakamlarına ve halkın beğenisine göre ölçen kuralın konması'], 'Ahmet Şuayp, Hüseyin Cahit ve Cenap Şahabettin sayesinde Türk eleştirisi sözcük düzeyindeki \'muaheze\'den çıkıp eserin bütününü ve sosyolojik-psikolojik arka planını inceleyen modern tenkide ulaşmıştır.'),
  ('Tevfik Fikret\'in \'Mâi Deniz\' şiirinde başlangıçta saf, duru ve masum bir çocuk gözü gibi parlayan denizin şiir sonunda fırtınalı ve bulanık bir hâl alması neyin sembolüdür?', 'Gençlik ümitlerinin hayatın acı gerçekleri karşısında yıkılıp karamsarlığa dönüşmesinin', ['Marmara Denizi\'ndeki mevsimlik lodos rüzgârlarının balık göçlerini engellemesinin', 'Osmanlı deniz ticaretinin yelkenli gemilerden buharlı zırhlılara geçiş sürecinin', 'Şairin yüzme bilmediği için derin sulardan duyduğu çocukluk korkusunun'], 'Mâi Deniz, Servetifünun\'un temel izleği olan \'hayal (mavi) - hakikat (siyah)\' çatışmasını denizin durgunluktan hırçınlığa geçişi üzerinden simgeleştirir.'),
  ('Tevfik Fikret\'in \'Haluk\'un Âmentüsü\' adlı şiirinde geleneksel inanç esasları yerine koyduğu düşünsel temel aşağıdakilerden hangisidir?', 'İnsan aklına, bilimsel ilerlemeye, evrensel kardeşliğe ve toprağın ortak vatan oluşuna dayalı hümanizm', ['Yalnızca güçlü ulusların hayatta kalma hakkı olduğunu savunan acımasız sosyal Darwinizm', 'Sanayi uygarlığını reddedip ilkel komünal köy yaşamına dönmeyi öğütleyen mistik doğacılık', 'İmparatorluğun kurtuluşunu mutlak monarşiye kayıtsız itaate bağlayan gelenekçi siyaset'], '\'Toprak vatanım, nev\'-i beşer milletim... İnsan / İnsan olur ancak bunu iz\'ânla, inandım\' diyen Fikret, Haluk\'un Âmentüsü\'nde bilimci, barışçı ve hümanist dünya görüşünü özetlemiştir.'),
  ('Batılı anlamda modern Türk romanının kurucusu kabul edilen Halit Ziya Uşaklıgil, İzmir yıllarında kaleme aldığı ilk roman denemesi Sefile\'den sonra hangi üç romanını İstanbul\'a taşınmadan önce yazmıştır?', 'Nemide, Bir Ölünün Defteri ve Ferdi ve Şürekâsı', ['Mai ve Siyah, Aşk-ı Memnu ve Kırık Hayatlar adlı büyük İstanbul romanlarını', 'Eylül, Genç Kız Kalbi ve Karanfil ve Yasemin başlıklı psikolojik tahlil eserlerini', 'Nadide, Hayal İçinde ve Zavallı Necdet adını taşıyan bireysel aşk anlatılarını'], 'Halit Ziya İzmir\'de Hizmet gazetesini çıkarırken Sefile\'nin ardından Nemide, Bir Ölünün Defteri ve Ferdi ve Şürekâsı romanlarını yazmıştır.'),
  ('Babasının ani ölümü üzerine ailesinin geçimini üstlenmek zorunda kalan Ahmet Cemil\'in çalıştığı Babıali gazetesinin adı ve kız kardeşi İkbal\'in ölümüne yol açan kaba mizaçlı damat kimdir?', 'Mir\'at-ı Şuun gazetesi ve Vehbi Bey', ['Tercüman-ı Hakikat gazetesi ve matbaa ortağı Raci Efendi', 'Servet-i Fünun mecmuası ve yalı komşusu Hüseyin Nazmi Bey', 'Sabah gazetesi ve başyazar yardımcısı Ali Şekip Efendi'], 'Ahmet Cemil Mir\'at-ı Şuun gazetesinde çalışır; matbaa sahibinin oğlu Vehbi Bey ile evlenen kız kardeşi İkbal, kocasının şiddeti yüzünden çocuğunu düşürüp hayatını kaybeder.'),
  ('Servetifünun kuşağının ortak beyannamesi sayılan Mai ve Siyah\'ta, Ahmet Cemil\'in eski tarz şiiri savunduğu için tartıştığı kıskanç ve yeteneksiz şair tipi aşağıdakilerden hangisidir?', 'Raci', ['Erenköy\'deki köşkünde Batı edebiyatı okuyan Hüseyin Nazmi', 'Matbaada dizgicilikten yetişen sessiz ve sadık Ali Şekip', 'Gazetenin başmuharriri olan hoşgörülü Hüseyin Baha Efendi'], 'Gazete yazarlarından Raci, Muallim Naci çevresini andıran eski edebiyat taraftarı, dedikoducu ve Ahmet Cemil\'in yeni tarz şiirini alaya alan karşıt tiptir.'),
  ('Tüm hayallerini yitiren Ahmet Cemil\'in Mai ve Siyah\'ın sonunda İstanbul\'dan ayrılırken yaptığı son sembolik eylem nedir?', 'Yıllarca emek verdiği şiir defterini sobada yakıp annesiyle Yemen\'e kaza kaymakamı olarak gitmesi', ['Hüseyin Nazmi\'nin aracılığıyla Paris Sefareti kâtipliğine atanarak Fransa vapuruna binmesi', 'Lamia\'nın düğün gecesinde Boğaziçi kıyısındaki kayalıklardan denize atlayarak canına kıyması', 'Matbaadaki hisselerini satarak Manisa\'da satın aldığı küçük çiftlik evine tek başına çekilmesi'], 'İkbal\'in ölümü ve Lamia\'nın bir subayla nişanlandığını öğrenmesi üzerine Ahmet Cemil, büyük eserini yakar ve siyah bir gecede annesiyle Yemen\'deki görevine doğru vapurla uzaklaşır.'),
  ('Yalının hanımı Bihter\'in amcasının çapkın yeğeni Behlül ile yaşadığı yasak ilişkiyi geceleri bahçede ve serada gizlice gözlemleyerek öğrenen ve Nihal\'e duyduğu karşılıksız bağlılıkla eriyip ölen karakter kimdir?', 'Habeş uşak Beşir', ['Peyker\'in eşi olan ve kayınvalidesinin entrikalarından bunalan Nihat Bey', 'Yalının emektar kalfası olup mutfak dedikodularını yöneten Şayeste Kadın', 'Adnan Bey\'in kâhyalığını yürüten ve hesap defterlerini tutan Süleyman Efendi'], 'Küçük yaşta yalıya alınmış sadık Habeşli uşak Beşir, Nihal\'i içten içe sever; Bihter ile Behlül\'ün ihanetine tanık olur ve ölüm döşeğinde gerçeği Adnan Bey\'e anlatır.'),
  ('Firdevs Hanım\'ın kızı Bihter\'den öç almak ve yalıdaki konumunu korumak amacıyla kurduğu hangi plan Aşk-ı Memnu\'da trajik sona giden düğümü tetikler?', 'Behlül ile Adnan Bey\'in genç kızı Nihal\'i birbirine yaklaştırıp nişanlanmalarını sağlaması', ['Bihter\'in yazdığı gizli aşk mektuplarını imzasız bir zarfla doğrudan Adnan Bey\'in odasına bırakması', 'Matmazel de Courton\'a iftira atarak mürebbiyenin Fransa\'ya geri gönderilmesine sebep olması', 'Adnan Bey\'in bütün mal varlığını kendi üzerine geçirmek için sahte borç senetleri düzenlemesi'], 'Firdevs Hanım, Behlül ile Nihal\'in evlenmesi fikrini ortaya atıp destekleyerek hem yalıda kalmayı planlar hem de Bihter\'i kıskançlık krizine sürükler.'),
  ('Natüralizm akımının \'soyaçekim\' (irsiyet) ilkesi Aşk-ı Memnu\'da hangi kurgusal çatışma üzerinden işlenmektedir?', 'Annesi Firdevs Hanım gibi olmamaya yemin eden Bihter\'in sonunda annesinin hafifmeşrep mizacına yenik düşmesi', ['Nihal\'in babası Adnan Bey\'den geçen oymacılık yeteneği sayesinde büyük bir heykeltraş olması', 'Behlül\'ün amcasından devraldığı tutumluluk alışkanlığıyla ticarette büyük servet biriktirmesi', 'Bülent\'in yatılı okulda tanıştığı yoksul arkadaşlarının etkisiyle konak yaşamına başkaldırması'], 'Halit Ziya, Hippolyte Taine ve Zola etkisindeki irsiyet yasasını Bihter\'in ne kadar dirense de \'Melih Bey takımının kanından\' kaçamayışı üzerinde somutlaştırmıştır.'),
  ('Doktor Ömer Behiç\'in Şişli\'de yaptırdığı yeni evdeki mutlu aile yuvasının, Veli Bey\'in hafifmeşrep kızı Neyyir\'in tuzağıyla sarsılmasını ve küçük kızı Leyla\'nın menenjitten ölümüyle vicdanına dönüşünü anlatan roman hangisidir?', 'Kırık Hayatlar', ['Bir Ölünün Defteri', 'Ferdi ve Şürekâsı', 'Nesl-i Ahir'], 'Halit Ziya\'nın Aşk-ı Memnu\'dan sonra en olgun eseri sayılan Kırık Hayatlar\'da Doktor Ömer Behiç, sadık eşi Vedide\'yi Neyyir ile aldatır; küçük kızı Leyla\'nın ölümüyle yıkılıp ailesine sığınır.'),
  ('Romanlarında hep İstanbul\'un seçkin köşk ve yalılarını anlatmakla eleştirilen Halit Ziya Uşaklıgil, hangi türünde kenar mahalle insanlarını, esnafı, bekçiyi ve Anadolu yaşamını başarıyla yansıtmıştır?', 'Öykülerinde (Solgun Demet, Hepsinden Acı, İzmir Hikâyeleri)', ['Manzum tiyatrolarında (Füruzan, Kâbus ve Fare piyeslerinde)', 'Mensur şiirlerinde (Mezardan Sesler adlı lirik kitabında)', 'Edebiyat kuramı yazılarında (Hikâye başlıklı incelemesinde)'], 'Romanlarında yüksek zümreye bağlı kalan Halit Ziya; \'Ferhunde Kalfa\', \'Mahalle Meclisi\', \'Kar Yağarken\' ve İzmir Hikâyeleri gibi öykülerinde alt tabaka ve taşra insanını gerçekçi biçimde işlemiştir.'),
  ('Sultan Mehmet Reşat döneminde dört yıl boyunca Mabeyn Başkâtipliği görevinde bulunan Halit Ziya\'nın saray gözlemlerini anlattığı anı eseri ile diplomat oğlu Halil Vedat\'ın intiharı üzerine yazdığı kitap hangileridir?', 'Saray ve Ötesi ile Bir Acı Hikâye', ['Kırk Yıl ile Edebiyat Hatıraları adlı anı ciltleri', 'Matbuat Hatıralarım ile Siyasal Anılar başlıklı yapıtlar', 'Zoraki Diplomat ile Mor Salkımlı Ev adlı hatıratlar'], 'Halit Ziya kırk yaşına kadarki edebî yaşamını Kırk Yıl\'da, Mabeyn Başkâtipliği dönemini Saray ve Ötesi\'nde, oğlu Halil Vedat\'ın acısını ise Bir Acı Hikâye\'de anlatmıştır.'),
  ('Platonik aşkın ve iç konuşmaların egemen olduğu Eylül romanında Necip\'in Suat\'a duyduğu gizli bağlılığı açığa çıkaran somut nesne ile romanın sonundaki felaket hangisidir?', 'Suat\'ın eldiveninin tekini Necip\'in saklaması ve kışlık konakta çıkan yangında ikisinin birlikte yanarak ölmesi', ['Piyano notasının arasına bırakılan veda mektubu ve Süreyya\'nın yelkenlisinin fırtınada alabora olması', 'Suat\'ın boynundaki madalyonun kaybolması ve Necip\'in tifoya yakalanarak sanatoryumda can vermesi', 'Günlük defterinin Hacer tarafından çalınması ve iki gencin İsviçre treninde zehir içerek intihar etmesi'], 'Necip hastalandığında yastığının altında Suat\'ın eldiveninin diğer teki bulunur; romanın sonunda kışın taşındıkları konakta yangın çıkınca Suat içeride kalır, onu kurtarmak için alevlere dalan Necip de onunla birlikte can verir.'),
  ('İzmir\'den İstanbul\'daki amcasının evine gelen kültürlü Pervin\'in, hayran olduğu ünlü şair Mehmet Behiç\'in gerçekte bayağı ve çıkarcı biri olduğunu görerek hayal kırıklığı yaşamasını günlük biçiminde anlatan Mehmet Rauf romanı hangisidir?', 'Genç Kız Kalbi', ['Ferda-yı Garam', 'Karanfil ve Yasemin', 'Son Yıldız'], 'Mehmet Rauf\'un Genç Kız Kalbi romanında Pervin, eserlerinden tanıdığı şair Mehmet Behiç\'in kadınları küçümseyen ve para için evlenen yüzünü görünce İzmir\'e dönmeye karar verir.'),
  ('Galatasaray Sultanisi öğrencisi genç Nezih\'in Tepebaşı Bahçesi\'nde gördüğü Rum kızı İzmaro\'yu meleksi bir varlık olarak düşlemesini, ancak kızın sıradan ve çıkarcı yüzünü öğrenince sarsılmasını anlatan Hüseyin Cahit romanı hangisidir?', 'Hayal İçinde', ['Nadide', 'Zavallı Necdet', 'Siyah Gözler'], 'Hüseyin Cahit Yalçın\'ın 1901 tarihli Hayal İçinde romanı, Servetifünun\'un temel teması olan \'hayal-hakikat tezadı\'nı lise öğrencisi Nezih\'in platonik yanılgısıyla işler.'),
  ('Hüseyin Cahit Yalçın\'ın Servetifünun topluluğunun Yeni Zelanda\'ya göçüp orada özgür ve uygar bir köy kurma ütopyasını hikâyeleştirdiği ünlü öykü kitabı aşağıdakilerden hangisidir?', 'Hayat-ı Muhayyel', ['Hayat-ı Hakikiye Sahneleri', 'Niçin Aldatırlarmış', 'Gönül Hanım'], '1899\'da yayımlanan Hayat-ı Muhayyel (Hayal Edilen Hayat), Servetifünuncuların istibdattan kaçıp doğada temiz bir koloni kurma özlemini doğrudan yansıtır.'),
  ('Yirmi dört yaşındaki Hüseyin Rahmi\'nin Ahmet Mithat Efendi tarafından Tercüman-ı Hakikat\'te büyük övgüyle tefrika edilen ilk romanı Şık\'ta, alafrangalığa özenip annesinin elmas küpelerini çalan gülünç kahraman kimdir?', 'Şatırzade Şöhret Bey', ['Paris\'ten yarım yamalak görgüyle dönen Meftun Bey', 'Kuyruklu yıldız korkusunu fırsata çeviren İrfan Galip', 'Çamlıca\'da lando arabasıyla dolaşan mirasyedi Bihruz Bey'], '1889 tarihli Şık romanında alafranga züppe Şatırzade Şöhret Bey, düşkün Fransız kadını Madam Potiş\'le Beyoğlu\'nda gezebilmek için annesinin küpelerini çalar ve köpek Drol yüzünden rezil olur.'),
  ('Aksaray\'daki mahalle konağında alafranga sofra dersi vermeye kalkışan Meftun Bey\'in, zengin cimri Kasım Efendi\'nin parasını ele geçirmek için kızı Edibe ile evlenip kayınbiraderi Mahir\'i intihara sürüklediği Hüseyin Rahmi romanı hangisidir?', 'Şıpsevdi', ['Gulyabani', 'Tesadüf', 'Nimetşinas'], 'İlk adı \'Alafranga\' iken sansürce engellenip 1911\'de Şıpsevdi adıyla basılan eserde, Paris görmüş züppe Meftun Bey\'in Doğu-Batı çatışması içindeki gülünç ve çıkarcı entrikaları anlatılır.'),
  ('Eserlerinde şive taklitlerine, mahalle kadınlarının dedikodularına, meddah tarzı ara bilgilere ve argoya geniş yer veren Hüseyin Rahmi Gürpınar\'ın roman tekniği hangi iki kaynağın sentezidir?', 'Geleneksel Türk halk seyirlik anlatısı (orta oyunu/meddah) ile Fransız natüralizmi', ['Divan edebiyatındaki süslü münşeat nesri ile İngiliz gotik şato romancılığı', 'Servetifünun\'un bireysel salon üslubu ile Rus sembolistlerinin mistik şiiri', 'Klasik Yunan trajedilerinin üç birlik kuralı ile İtalyan fütürizminin hız tutkusu'], 'Hüseyin Rahmi bir yandan Karagöz, orta oyunu ve Ahmet Mithat\'ın meddah geleneğinden beslenirken, öte yandan Emile Zola ve Paul Bourget tarzı deneysel-gözlemci natüralizmi uygulamıştır.'),
  ('İstanbul\'un değişen kılık kıyafetini, sokak satıcılarını, mesire yerlerini ve toplumsal tiplerini canlı gözlemlerle aktaran Ahmet Rasim\'in fıkra ve sohbet kitapları aşağıdakilerden hangisinde doğru gruplanmıştır?', 'Şehir Mektupları, Eşkal-i Zaman, Muharrir Bu Ya ve Gülüp Ağladıklarım', ['Bize Göre, Gurebahane-i Laklakan ve Frankfurt Seyahatnamesi', 'Evrak-ı Eyyam, Tiryaki Sözleri ve Nesr-i Harp Nesr-i Sulh', 'Eğil Dağlar, Aziz İstanbul ve Siyasi ve Edebi Portreler'], 'Ahmet Rasim\'in Malumat\'ta tefrika ettiği Şehir Mektupları ile Eşkal-i Zaman, Cidd ü Mizah, Ramazan Sohbetleri, Muharrir Bu Ya ve Gülüp Ağladıklarım fıkra/sohbet türünün klasikleridir.'),
  ('Halit Ziya Uşaklıgil\'in İzmir\'deyken yayımladığı \'Hikâye\' adlı inceleme kitabında savunduğu edebî görüş hangi açıdan önem taşır?', 'Romantizmin abartılı hayalciliğini eleştirip gözlem ve belgeye dayalı realist roman yöntemini kuramsallaştırması', ['Halk hikâyelerindeki Âşık Garip ve Kerem ile Aslı kollarının aynen sürdürülmesini önermesi', 'Roman türünün Türk aile yapısına zarar verdiği gerekçesiyle yalnızca tarih yazılmasını istemesi', 'Mensur şiir dışında hiçbir düzyazı türünün estetik değer taşıyamayacağını iddia etmesi'], '1889\'da basılan \'Hikâye\', Türk edebiyatında roman ve öykü türünün tarihçesini ve realist-natüralist kuramını inceleyen ilk müstakil kuramsal eserlerden biridir.'),
  ('Halit Ziya\'nın \'Ferhunde Kalfa\' adlı ünlü öyküsünde bir konağa çocuk yaşta alınıp ömrü boyunca \'yakında gelin edilecek\' vaadiyle oyalanan Habeşli dadının dramı nasıl noktalanır?', 'Konağın küçük hanımının bile çocuk sahibi olduğunu gördükten sonra yaşlı ve kambur hâliyle göstermelik evlendirildiği gece sevinç ve heyecandan ölmesi', ['Yıllarca biriktirdiği bahşiş altınlarıyla Üsküdar\'da küçük bir aktar dükkânı açarak konaktan bağımsızlığını kazanması', 'Azat belgesini alır almaz memleketine dönen bir hacı kafilesine katılıp İstanbul\'dan sonsuza dek ayrılması', 'Konak yangınında ailenin mücevher kutusunu kurtarmaya çalışırken çöken tavanın altında kalarak can vermesi'], 'Halit Ziya\'nın en dokunaklı öykülerinden Ferhunde Kalfa\'da, saçları ağardıktan sonra yaşlı bir uşakla evlendirilen kalfa, gerdek gecesi ömrü boyunca beklediği gelinlik sevincine kalbi dayanamayıp vefat eder.'),
  ('Mai ve Siyah romanında Ahmet Cemil\'in en yakın dostu olup Erenköy\'deki köşkünde zengin kütüphanesiyle yaşayan ve Dışişleri memurluğuyla Avrupa\'ya gideceği sırada Ahmet Cemil\'i yalnız bırakan karakter kimdir?', 'Hüseyin Nazmi', ['Mir\'at-ı Şuun\'un başyazarı Hüseyin Baha Efendi', 'Matbaa makinelerinin başında verem olan Ali Şekip', 'Gazetede eski edebiyatı savunan kıskanç şair Raci'], 'Hüseyin Nazmi, Lamia\'nın ağabeyi ve Ahmet Cemil\'in sanat sırdaşıdır; varlıklı olduğu için hayallerine kavuşup Avrupa görevine giderken yoksul Ahmet Cemil yıkıma sürüklenir.'),
  ('Ahmet Rasim\'in \'İlk Sevgi\', \'Güzel Eleni\', \'Meyl-i Dil\' ve \'Ülfet\' (Hamamcı Ülfet) gibi kurmaca anlatıları edebiyatımızda hangi geleneğin devamı niteliğindedir?', 'Ahmet Mithat Efendi tarzı popüler, öğretici ve İstanbul\'un orta tabaka yaşamını yansıtan hikâyeciliğin', ['Halit Ziya Uşaklıgil\'in ağır sanatkârane tamlamalarla örülü psikolojik salon romancılığının', 'Ömer Seyfettin\'in Türk tarihindeki sınır savaşlarını konu alan epik-milli öykücülüğünün', 'Sait Faik Abasıyanık\'ın olay örgüsünü tamamen dışlayan çağrışımcı durum hikâyeciliğinin'], 'Ahmet Rasim roman ve uzun öykülerinde (\'Cep Romanları\' tarzında) Ahmet Mithat\'ın halka dönük, sade ve ibret verici anlatım çizgisini sürdürmüştür.'),
  ('Hüseyin Rahmi Gürpınar\'ın 1924\'te yayımladığı \'Efsuncu Baba\' romanında büyücülük ve simya peşinde koşan Agop ile İspanyol define arayıcısının serüvenleri hangi toplumsal eleştiriyi taşır?', 'Emek harcamadan tılsım ve üfürükçülükle zengin olmaya çalışan batıl zihniyetin gülünçlüğünü', ['Kimya laboratuvarlarında yapılan bilimsel deneylerin çevre sağlığına verdiği zararları', 'Azınlık tüccarların dış ticarette kurdukları banka ortaklıklarının hukuki boşluklarını', 'Üniversite gençliğinin felsefe derslerinde materyalist akımlara kapılmasının tehlikelerini'], 'Hüseyin Rahmi Gulyabani, Cadı ve Efsuncu Baba gibi romanlarında halkın cehaletinden beslenen büyücü, üfürükçü ve define hurafelerini keskin bir mizahla teşhir etmiştir.'),
  ('Mehmet Rauf\'un \'Karanfil ve Yasemin\' romanında Avrupa\'dan dönen Samim\'in iki farklı kadın tipi (evli ve tutkulu Nevhiz ile saf genç kız Pertev) arasında kalması hangi izleği sürdürür?', 'Yasak aşk heyecanı ile huzurlu evlilik arzusu arasında bocalayan iradesiz erkek psikolojisini', ['Milli Mücadele cephelerine silah kaçıran gizli teşkilat üyelerinin fedakârlık sınavını', 'Doğu müziği makamlarıyla Batı senfonilerini birleştirmeye çalışan bir bestecinin sanat kavgasını', 'İflas eden bir Osmanlı paşasının alacaklı bankerlere karşı yürüttüğü hukuk mücadelesini'], 'Karanfil (tutkulu ve yakıcı Nevhiz) ile Yasemin (masum Pertev) sembolizmi üzerinden Mehmet Rauf, yüksek sosyetedeki yozlaşmış aşk üçgenini işler.'),
  ('Hüseyin Rahmi Gürpınar\'ın Heybeliada\'daki köşkünde kırk yıla yakın münzevi bir hayat sürerken örgü örmesi, reçel kaynatması ve bisiklete binmesiyle birlikte eserlerinde kadınlar arası konuşmaları çok canlı yazabilmesi nasıl açıklanır?', 'Çocukluğundan beri teyze, anneanne ve dadılar arasında büyüyüp kadın meclislerinin dilini kusursuz gözlemlemesiyle', ['Kadın dergilerinde sahte kadın imzalarıyla otuz yıl boyunca başyazarlık yapmış olmasıyla', 'Kız öğretmen okullarında uzun yıllar diksiyon ve ev ekonomisi dersleri vermesiyle', 'Fransız kadın yazarların romanlarını kelime kelime Türkçeye uyarlayarak yayımlamasıyla'], 'Küçük yaşta annesini kaybedip kadınlarla dolu konak/mahalle ortamında büyüyen Hüseyin Rahmi, İstanbul kadınlarının deyimlerini, beddualarını ve sohbet kıvraklığını Türk edebiyatında en doğal yansıtan yazardır.'),
  ('Mai ve Siyah\'ta Ahmet Cemil\'in matbaa makinelerinin çıkardığı tekdüze demir gürültüsünü kendi beynini ve gençliğini öğüten bir canavar gibi algılaması hangi anlatım tekniğinin başarılı bir örneğidir?', 'Dış mekan ve nesne betimlemelerini kahramanın karamsar ruh hâline göre öznel biçimde renklendirmenin', ['Sanayi Devrimi\'nin baskı teknolojisinde yarattığı üretim artışını sayısal verilerle övmenin', 'İşçi sınıfının sendikal haklarını savunan politik bir grev bildirisi kaleme almanın', 'Okura matbaacılık mesleğinin teknik terimlerini ansiklopedik dipnotlarla öğretmenin'], 'Halit Ziya, mekan-insan bütünleşmesini ustalıkla kurar; Ahmet Cemil mutsuzken Süleyman Efendi\'nin matbaasındaki makineler bile can çekişen, inleyen karanlık birer varlığa dönüşür.'),
  ('Aşk-ı Memnu romanında Melih Bey takımının bir diğer üyesi olan Bihter\'in ablası Peyker, kardeşi Bihter\'den hangi karakter özelliğiyle kesin biçimde ayrılır?', 'Behlül\'ün geçici heveslerine yüz vermeyip eşine ve çocuğuna bağlı dengeli bir aile yaşamını korumasıyla', ['Annesi Firdevs Hanım\'la iş birliği yaparak Adnan Bey\'in yalısını gizlice satın almaya çalışmasıyla', 'Kocası Nihat Bey\'i terk edip Paris\'teki moda evlerinde mankenlik yapmaya gitmesiyle', 'Nihal\'in piyano derslerini yasaklayarak yalıda katı ve baskıcı bir yönetim kurmasıyla'], 'Halit Ziya soyaçekim yasasını mutlaklaştırmamak için Peyker\'i iradesiyle annesinin kaderini aşabilen sağduyulu bir eş ve anne olarak Bihter\'in karşısına yerleştirmiştir.'),
  ('Servetifünun romanlarında zaman kurgusu incelendiğinde \'Mai ve Siyah, Aşk-ı Memnu ve Eylül\' gibi başyapıtların ortak teknik özelliği aşağıdakilerden hangisidir?', 'Şimdiki zamandan geriye dönüşlerle (flashback) karakterlerin geçmişlerinin aydınlatılıp olayların birkaç yıla yayılması', ['Kahramanların doğumundan ölümüne dek altmış yıllık sürecin kronolojik sırayla hiç atlanmadan anlatılması', 'Tüm olayların yalnızca yirmi dört saatlik tek bir zaman dilimine sıkıştırılarak sahnelenmesi', 'Tarih öncesi devirlerden geleceğin uzay çağına sıçrayan bilimkurgu zaman kurgusunun uygulanması'], 'Halit Ziya ve Mehmet Rauf olayları kriz noktasına yakın bir şimdiki zamanda başlatıp (örneğin Tepebaşı yemeği veya Boğaz\'da sandal gezintisi) geriye dönüşlerle karakterlerin geçmişini verir.'),
  ('Kırık Hayatlar romanında Doktor Ömer Behiç\'in hastalarını muayene ederken İstanbul\'daki pek çok ailenin gizli ihanet ve mutsuzluklarla çatırdadığını görmesi romana nasıl bir boyut kazandırır?', 'Ana olay örgüsünün yanına farklı evlilik dramlarını ekleyen panoramik bir toplumsal gözlem derinliği', ['Tıp fakültesi öğrencileri için bulaşıcı hastalıkların tedavi reçetelerini sıralayan bilimsel bir kılavuz niteliği', 'Polisiye cinayet vakalarını adli tıp otopsileriyle çözen gerilimli bir dedektiflik kurgusu', 'Yoksul köylülerin ücretsiz muayene edilmesini savunan sosyalist bir sağlık politikası bildirisi'], 'Doktor Ömer Behiç mesleği gereği girdiği konaklarda \'kırık hayatlar\'a tanık olurken zamanla kendisi de Neyyir yasak aşkıyla aynı ahlaki çöküşün parçası hâline gelir.'),
  ('Mehmet Rauf\'un edebiyat dünyasındaki dostluklarını, Servet-i Fünun yıllarını, Halit Ziya ve Tevfik Fikret\'le ilişkilerini ölümünden kısa süre önce kaleme aldığı anı metinleri hangi adla bilinir?', 'Edebiyat Hatıraları', ['Saray ve Ötesi', 'Falaka ve Gecelerim', 'Türk\'ün Ateşle İmtihanı'], 'Mehmet Rauf\'un dergilerde yayımlanan ve sonradan \'Edebiyat Hatıraları\' (Edebî Hatıralar) başlığıyla derlenen anıları, Servetifünun kuşağının iç dünyasına ışık tutar.'),
  ('Ahmet Rasim\'in II. Meşrutiyet sonrasında Hüseyin Rahmi Gürpınar ile birlikte çıkardığı ve dönemin siyasal-toplumsal çalkantılarını halk diliyle tiye alan mizah gazetesi hangisidir?', 'Boşboğaz ile Güllabi', ['Diyojen ile Çıngıraklı Tatar', 'Akbaba ile Papağan', 'Aydede ile Karagöz'], 'İki yakın dost ve halk dili ustası olan Hüseyin Rahmi ile Ahmet Rasim, 1908 Meşrutiyet\'inin hemen ardından 36 sayı süren ünlü \'Boşboğaz ile Güllabi\' mizah gazetesini çıkarmışlardır.'),
  ('Mai ve Siyah\'ta Ahmet Cemil\'in yazmayı düşlediği \'insan hayatını doğuşundan ölümüne dek mevsimler ve müzik temaları gibi işleyen kırk-elli sayfalık büyük manzum eser\' onun hangi poetik idealini yansıtır?', 'Eski divan nazmını aşarak Batılı sembolist-parnasyen tarzda bütünlüklü ve müzikal bir yeni Türk şiiri kurma tutkusunu', ['Halk âşıklarının koşma ve destanlarını derleyerek hece ölçüsüyle ulusal bir kahramanlık epopesi yazma hedefini', 'Felsefi ve bilimsel yasaları kuruluktan kurtarmak için fizik kurallarını mesnevi biçiminde öğretme projesini', 'Saray törenlerinde okunmak üzere padişahın zaferlerini öven görkemli bir şehname hazırlama arzusunu'], 'Ahmet Cemil karakteri aslında Tevfik Fikret ve Cenap Şahabettin kuşağının şiir idealini temsil eder; onun hayalindeki eser de Servetifünun\'un yeni şiir estetiğidir.'),
  ('Mehmet Rauf\'un \'Siyah İnciler\' kitabındaki mensur şiirleri Halit Ziya\'nın \'Mensur Şiirler\'inden ayıran başlıca üslup özelliği nedir?', 'Ağır tamlamaların nispeten azaltılıp konuşma diline daha yakın, akıcı ve Baudelairevari melankolik bir ritim kurulması', ['Tamamının toplumsal adaletsizlik ve işçi hakları üzerine sert politik bildirilerden oluşması', 'Her parçanın sonunda okura ahlaki bir kıssadan hisse veren atasözleriyle bağlanması', 'Yalnızca Anadolu bozkırının coğrafi güzelliklerini pastoral bir neşeyle betimlemesi'], 'Halit Ziya\'nın Mensur Şiirler\'i daha süslü ve ağır bir inşâ/sanat dili taşırken, Mehmet Rauf Siyah İnciler\'de dili daha kıvrak, samimi ve müzikal hâle getirmiştir.'),
  ('Fecriati Beyannamesi\'nde topluluk üyelerinin halkı aydınlatmak ve edebiyat zevkini yaymak amacıyla yapmayı vaat ettikleri etkinlikler arasında hangisi yer alır?', 'Batı\'nın önemli eserlerini Türkçeye çevirip bir Fecriati Kütüphanesi kurmak ve halka açık konferanslar vermek', ['Anadolu köylerine gezici tiyatro kumpanyaları göndererek okuma yazma seferberliği başlatmak', 'Divan şiiri geleneğini yeniden canlandırmak için medreselerde aruz ve belagat kürsüleri açmak', 'Balkan dillerindeki halk destanlarını derleyerek ortak bir Osmanlı ulusal mitolojisi oluşturmak'], 'Beyannamede Fecriati Kütüphanesi dizisi yayımlamak, açık konferanslar düzenlemek ve Batı\'daki benzer sanat kurumlarıyla ilişki kurmak hedeflenmiştir.'),
  ('Fecriati topluluğu üyeleri Servetifünun kuşağını hangi gerekçeyle eleştirerek kendilerini onlardan ayırmaya çalışmışlardır?', 'Edebiyatı yeterince ciddiye almayıp Batı edebiyatını yüzeysel aktarmaları ve Meşrutiyet\'ten sonra sanat sahnesinden çekilmeleri', ['Şiirde aruz ölçüsünü tamamen bırakıp halk türkülerinin kaba söyleyişine teslim olmaları', 'Romanlarında İstanbul sosyetesi yerine yalnızca taşra eşrafının toprak kavgalarını işlemeleri', 'Fransız sembolistlerini görmezden gelerek yalnızca Alman romantik felsefesine bağlanmaları'], 'Fecriaticiler, Edebiyat-ı Cedidecileri Batı\'ya tam açılamamakla ve 1901 sonrasında edebiyatı yalnız bırakmakla suçlamış, ancak pratikte onların devamı olmaktan kurtulamamışlardır.'),
  ('Fecriati topluluğunun Türk edebiyatı tarihinde kısa sürede dağılmasının en temel estetik ve düşünsel nedeni aşağıdakilerden hangisidir?', 'Bireysel özgürlüğü savunurken ortak ve özgün bir sanat programı kuramamaları ve yükselen Millî Edebiyat akımının toplumsal gerçekliğine yenik düşmeleri', ['İttihat ve Terakki hükümetinin topluluk bildirisini vatan hainliği sayarak bütün üyeleri Fizan\'a sürgüne göndermesi', 'Topluluk üyelerinin tamamının hece ölçüsünü reddettikleri için matbaa sahiplerinin eserlerini basmayı boykot etmesi', 'Servetifünun dergisinin kapanması üzerine ülkede edebiyat yazısı yayımlayacak hiçbir gazete veya mecmuanın kalmaması'], 'Balkan Savaşları\'nın sarsıcı ortamında \'Sanat şahsi ve muhteremdir\' anlayışı karşılık bulamamış; Yakup Kadri, Fuat Köprülü, Ali Canip gibi üyeler Millî Edebiyat saflarına geçmiştir.'),
  ('Adalar (özellikle Büyükada) coğrafyasını şiirlerinin fonu yaptığı için edebiyat çevrelerinde \'Adalar Şairi\' unvanıyla anılan ve \'Ruh-ı Bikayd\' adlı şiir kitabıyla bilinen Fecriatici kimdir?', 'Tahsin Nahit', ['Emin Bülent Serdaroğlu', 'Celal Sahir Erozan', 'Faik Ali Ozansoy'], 'Tahsin Nahit marazi duyarlıklı aşk ve doğa şiirlerini \'Ruh-ı Bikayd\'da toplamış, Adalar atmosferini işlediği için \'Adalar Şairi\' olarak tanınmıştır.'),
  ('Fecriati topluluğu Servet-i Fünun dergisinden ayrıldıktan sonra görüşlerini ve ürünlerini esas olarak hangi dergi çevresinde yayımlamayı sürdürmüştür?', 'Rübab', ['Hazine-i Fünun', 'Çocuk Bahçesi', 'Mecmua-i Ebüzziya'], 'Şehabettin Süleyman, Cemil Süleyman, Tahsin Nahit ve genç kuşak şairlerin toplandığı \'Rübab\' (1912-1914) dergisi, Fecriati\'nin son dönem yayın organı ve Nayiler gibi arayışların odağı olmuştur.'),
  ('\'Yeni Lisan\' makalesinin ilk sayısında yazar adı yerine \'？\' (soru işareti) kullanılmasının temel nedeni aşağıdakilerden hangisidir?', 'Görüşlerin tek bir kişinin şahsi fikri gibi değil, dergi etrafında toplanan genç kuşağın ortak davası olarak algılanmasını sağlamak', ['Ömer Seyfettin\'in orduda görevli bir subay olması nedeniyle askeri mahkemede idamla yargılanmaktan korkması', 'Matbaa dizgicisinin makale başlığının altındaki yazar imzasını mürekkep dağılması yüzünden okuyamaması', 'İstanbul\'daki Servetifünun yazarlarını meraklandırıp derginin tirajını ticari bir reklam hilesiyle artırmak'], 'Ömer Seyfettin tarafından kaleme alınan ilk Yeni Lisan başyazısı, kişisel polemiklere çekilmemesi ve kolektif bir manifesto niteliği taşıması için soru işareti imzasıyla yayımlanmıştır.'),
  ('Cenap Şahabettin ve Süleyman Nazif gibi isimlerin Genç Kalemler\'in Yeni Lisan hareketine karşı yürüttükleri sert muhalefetin temel dayanağı nedir?', 'Yüzyıllar içinde işlenmiş Osmanlıca terkiplerin atılmasının dilin estetik inceliğini, müzikalitesini ve kavram zenginliğini yoksullaştıracağı iddiası', ['İstanbul Türkçesi yerine Erzurum ve Konya ağızlarının resmi devlet dili yapılmasının ulusal birliği bozacağı endişesi', 'Latin alfabesine derhal geçilmediği sürece sadeleştirme çabalarının hiçbir bilimsel sonuç vermeyeceği düşüncesi', 'Halk masallarının toplanmasının medrese öğrencilerini felsefe ve astronomi derslerinden uzaklaştıracağı kaygısı'], 'Cenap Şahabettin ve Süleyman Nazif, \'üslup ve sanat\' kaygısıyla Farsça-Arapça tamlamaları dilin kazanılmış serveti saymış ve Yeni Lisan\'ı dili kabalaştırmakla suçlamışlardır.'),
  ('Yahya Kemal Beyatlı ile Yakup Kadri Karaosmanoğlu\'nun 1912 sonrasında kısa bir süre savundukları \'Nev-Yunanilik\' (Havza Edebiyatı) eğiliminin temel tezi aşağıdakilerden hangisidir?', 'Akdeniz havzası medeniyetine yerleşen Türklerin edebiyat köklerini İran yerine eski Yunan-Latin klasiklerinin duru ve ölçülü sanatında araması gerektiği', ['Modern Türk şiirinin Bizans kilise ilahilerini hece ölçüsüne uyarlayarak mistik bir Ortodoks-İslam sentezi kurması gerektiği', 'Osmanlı Devleti\'nin Balkanlar\'daki toprak kayıplarını önlemek için Yunancanın okullarda ikinci zorunlu edebiyat dili yapılması', 'Divan şiirindeki bütün mazmunların İskandinav ve Germen mitolojisindeki savaş tanrılarıyla değiştirilmesi zorunluluğu'], 'Fransa\'da Jean Moréas\'ın klasik dönüşünden etkilenen Yahya Kemal (\'Sicilya Kızları\', \'Biblos Kadınları\') ve Yakup Kadri (\'Siyah Saçlı Yabancı ile Berrak Gözlü Genç Kızın Sözleri\'), Akdeniz-Yunan duruluğunu önermişlerdir.'),
  ('Millî Mücadele yıllarında (1921-1923) Mustafa Şekip Tunç ve Yahya Kemal çevresinde yayımlanan, Anadolu direnişini Henri Bergson\'un \'yaratıcı hamle ve sezgi\' felsefesiyle destekleyen dergi hangisidir?', 'Dergâh', ['Aydede', 'Peyam-ı Sabah', 'Güleryüz'], 'Yahya Kemal\'in \'Üç Tepe\' yazısıyla yön verdiği Dergâh mecmuası, Ahmet Hamdi Tanpınar, Nurullah Ataç, Ahmet Kutsi Tecer gibi Cumhuriyet kuşağını yetiştirmiş ve Millî Mücadele\'nin manevi kalesi olmuştur.'),
  ('Abdullah Cevdet\'in Cenevre, Kahire ve İstanbul\'da uzun yıllar yayımladığı, radikal Batılılaşma fikirleri ve edebi anketleriyle II. Meşrutiyet\'ten Cumhuriyet\'e tartışmalar yaratan dergi hangisidir?', 'İçtihat', ['Sırat-ı Müstakim', 'Beyanülhak', 'Ceride-i Havadis'], '1904-1932 yılları arasında çıkan \'İçtihat\' dergisi, Batıcılık düşüncesinin merkez yayın organı olmuş; dil, kadın hakları, alfabe ve edebiyat tartışmalarına sahne olmuştur.'),
  ('Yeni Osmanlılar Cemiyeti\'nin yurt dışında (Londra ve Cenevre\'de) Namık Kemal ile Ziya Paşa yönetiminde çıkardığı ve \'Şiir ve İnşa\' makalesinin yayımlandığı muhalif gazete hangisidir?', 'Hürriyet', ['Basiret', 'Sabah', 'Mizan'], '1868\'de Londra\'da yayımlanmaya başlayan \'Hürriyet\' gazetesi, meşrutiyet fikrinin yanı sıra Ziya Paşa\'nın halk şiirini ve konuşma dilini öven ünlü \'Şiir ve İnşa\' yazısına da ev sahipliği yapmıştır.'),
  ('Ali Suavi\'nin 1867\'de İstanbul\'da çıkarıp sansür üzerine Londra\'da sürdürdüğü, yalın Türkçeyi ve ulusal eğitim konularını sert bir muhalefet diliyle işlediği gazete hangisidir?', 'Muhbir', ['İbret', 'Hadika', 'Devir'], 'Ali Suavi\'nin çıkardığı \'Muhbir\', hem İstanbul\'da hem Londra\'da Yeni Osmanlılar hareketinin ilk ve keskin dilli muhalefet yayınlarından biri olmuştur.'),
  ('Namık Kemal\'in Avrupa dönüşü 1872\'de başyazarlığını üstlendiği, \'Vatan yahut Silistre\' öncesinde hürriyetçi ve vatansever başmakaleleriyle halkı coşturan fikir gazetesi hangisidir?', 'İbret', ['Takvim-i Ticaret', 'Mecmua-i Fünun', 'Mir\'at-ı Âlem'], 'Namık Kemal, Ebüzziya Tevfik, Nuri ve Reşat beylerin çıkardığı \'İbret\' gazetesi (1872-1873), Tanzimat\'ın en etkili siyasal ve edebi düşünce gazetelerinden biridir.'),
  ('Münif Paşa öncülüğünde Cemiyet-i İlmiye-i Osmaniye tarafından 1862\'de çıkarılan ve felsefe, iktisat, doğa bilimleri üzerine makaleler içeren ilk Türk bilim-kültür dergisi hangisidir?', 'Mecmua-i Fünun', ['Servet-i Fünun', 'Mektep Mecmuası', 'Genç Kalemler'], 'Münif Paşa\'nın kurduğu \'Mecmua-i Fünun\', Batı bilimi ve aydınlanma düşüncesini Osmanlı aydınına tanıtan ilk süreli Türk dergisidir.'),
  ('1897 yılında Ahmet Mithat Efendi\'nin Tercüman-ı Hakikat\'te başlattığı, Ahmet Cevdet, Cenap Şahabettin ve Hüseyin Daniş\'in katıldığı \'Klasikler Tartışması\'nın ana sorusu nedir?', 'Türk edebiyatının kendi klasik dönemini yaşayıp yaşamadığı ve Batı klasiklerinin Türkçeye çevrilmesinin gerekli olup olmadığı', ['Okullarda Yunan mitolojisi öğretilmesinin İslam akaidine ve devlet sansürüne aykırı düşüp düşmediği', 'Molière komedyalarının geleneksel Karagöz perdesine uyarlanırken vezin kullanılıp kullanılmayacağı', 'Fuzuli ve Baki divanlarının yeni harflerle sadeleştirilerek köylere ücretsiz dağıtılıp dağıtılmayacağı'], 'Ahmet Mithat \'İkram-ı Aklam\' yazısıyla Corneille, Racine, Shakespeare gibi Batı klasiklerinin çevrilmesini önermiş; Cenap Şahabettin ise bizim henüz klasik devrimizi yaşamadığımızı savunmuştur.'),
  ('Tanzimat döneminde Beşir Fuat ile Menemenlizade Mehmet Tahir arasında Victor Hugo monografisi vesilesiyle başlayan edebî tartışmanın merkezindeki çatışma aşağıdakilerden hangisidir?', 'Pozitivist ve natüralist \'hakikat\' (gerçekçilik) anlayışı ile romantik ve duygusal \'hayaliyûn\' (hayalcilik) anlayışı arasındaki çatışma', ['Arapça-Farsça tamlamaların korunması ile bütün yabancı kelimelerin dilden tasfiye edilmesi arasındaki dil kavgası', 'Tiyatro eserlerinin sahnelenmek için mi yoksa yalnızca evde okunmak için mi yazılması gerektiği tartışması', 'Divan şiirindeki müstezat nazım biçiminin serbest müstezata dönüştürülmesinin aruz kalıplarını bozup bozmadığı sorunu'], '\'Hayaliyûn - Hakikiyûn\' tartışması olarak bilinen bu polemikte ilk Türk pozitivist-natüralisti Beşir Fuat bilimsel gerçekçiliği (Émile Zola), Menemenlizade Tahir ise şairane duyarlılığı savunmuştur.'),
  ('Kiralık Konak romanında başlangıçta Seniha\'ya platonik bir aşkla bağlı içli bir Fecriati şairiyken, Çanakkale Savaşı\'nda ulusal bilince ulaşıp cephede şehit düşen karakter kimdir?', 'Hakkı Celis', ['Faik Bey', 'Servet Bey', 'Ahmet Celal'], 'Hakkı Celis, bireysel ve marazi aşkından sıyrılarak \'milletin ıstırabını\' keşfeden ve Çanakkale\'de şehit olan idealist aydın dönüşümünü (Fecriati\'den Millî Edebiyat\'a geçişi) simgeler.'),
  ('Yakup Kadri\'nin Bektaşi tekkelerinin gerçek irfan ocağı olmaktan çıkıp dünyevi çıkar ve cinsel tutku mekanına dönüşmesini Nigâr Hanım\'ın trajedisi üzerinden anlattığı romanı hangisidir?', 'Nur Baba', ['Vurun Kahpeye', 'Yeşil Gece', 'Sinekli Bakkal'], 'Yayımlandığında büyük tartışma yaratan \'Nur Baba\' (1922), karizmatik tekke şeyhi Nur Baba\'nın evli ve varlıklı Nigâr Hanım\'ı kendine bağlayıp servetini tükettikten sonra daha genç Süheyla\'ya yönelmesini anlatır.'),
  ('Yakup Kadri\'nin II. Meşrutiyet yıllarındaki İttihat ve Terakki - Hürriyet ve İtilaf kavgalarını muhalif gazeteci Ahmet Kerim\'in gözünden anlattığı \'parti romanı\' hangisidir?', 'Hüküm Gecesi', ['Yaban', 'Ankara', 'Hep O Şarkı'], '1927\'de yayımlanan \'Hüküm Gecesi\', Yakup Kadri\'nin yakın dostu gazeteci Ahmet Samim\'in öldürülmesi başta olmak üzere Meşrutiyet devrinin sert siyasal boğuşmalarını işler.'),
  ('Yaban romanında köy halkını sömüren çıkarcı güç odaklarını temsil eden yerel ağa ve sahte din adamı ikilisi hangi seçenekte doğru eşleştirilmiştir?', 'Salih Ağa - Şeyh Yusuf', ['Hacı Fettah - Uzun Hüseyin', 'Hüseyin Nazmi - Reşit Bey', 'Kâmran Bey - Muhtar Süleyman'], 'Çarıklı tefeci Salih Ağa köylüyü ekonomik olarak kendisine köle ederken, gezginci Şeyh Yusuf hurafeler ve muska ticaretiyle halkın kaderci uyuşukluğunu besler.'),
  ('Yakup Kadri\'nin \'Ankara\' (1934) romanında başkahraman Selma Hanım\'ın üç ayrı dönemde yaptığı üç evlilik hangi tarihsel ve ideolojik aşamaları simgeler?', 'Mütareke aydınının çekingenliğini (Nazif), Cumhuriyet sonrasının çıkarcı bürokrasisini (Hakkı Bey) ve idealist devrimci Cumhuriyet inşasını', ['Tanzimat konak hayatını, Servetifünun salon edebiyatını ve Fecriati\'nin bireysel melankolisini', 'Osmanlı saray diplomasisini, İttihatçı komitacılığı ve çok partili serbest piyasa girişimciliğini', 'Köy tarım ekonomisini, yabancı sermayeli madenciliği ve ağır sanayi sendikacılığını'], 'Üç bölümden oluşan \'Ankara\' romanında Selma Hanım\'ın eşleri (bankacı Nazif, arsa spekülatörü Binbaşı Hakkı Bey ve toplumcu yazar Neşet Sabit), Cumhuriyet ideallerinin geçirdiği sınavları ve ütopik geleceği simgeler.'),
  ('Yakup Kadri\'nin II. Abdülhamit istibdadından kaçarak İzmir\'den Paris\'e giden Jön Türk Doktor Hikmet\'in Avrupa\'daki hayal kırıklığını ve veremden ölümünü işlediği romanı hangisidir?', 'Bir Sürgün', ['Panorama', 'Hep O Şarkı', 'Zoraki Diplomat'], '1937\'de yayımlanan \'Bir Sürgün\', Fransız kültürüne hayran Doktor Hikmet\'in Paris\'te hem yozlaşmış Jön Türk çevreleri hem Batı\'nın kayıtsızlığı karşısında yaşadığı yabancılaşmayı anlatır.'),
  ('Halide Edip Adıvar\'ın ilk dönem bireysel-psikolojik romanlarının başyapıtı sayılan ve mektup tekniğiyle kurgulanan \'Handan\' romanında Handan kiminle yaptığı mutsuz evlilikle yıpranırken kime aşık olur?', 'Hüsnü Paşa ile mutsuz bir evlilik yaşarken kuzeni Neriman\'ın eşi Hüseyin Nazım\'dan sonra Refik Cemal\'e aşık olur', ['Peyami Bey ile nişanlıyken cephe komutanı Binbaşı İhsan\'a tutularak Anadolu\'ya hemşire olarak geçer', 'Kız Tevfik ile evlenip sürgüne gönderildikten sonra İtalyan piyanist Peregrini ile hayatını birleştirir', 'Naim Efendi\'nin torunu Cemil ile evlenip savaş zengini Faik Bey uğruna konağı terk eder'], '1912\'de yayımlanan \'Handan\'da sosyalist devrimci Hüseyin Nazım kendisiyle fikir evliliği önerince kırılıp çapkın Hüsnü Paşa ile evlenen Handan, beyin humması nekahetinde Refik Cemal\'le yaşadığı yasak aşkın vicdan azabıyla ölür.'),
  ('Halide Edip\'in Ziya Gökalp ve Yusuf Akçura çevresindeki Türkçülük ideolojisinden etkilenerek yazdığı, Kaya (Samiye) ve Oğuz karakterleriyle âdemimerkeziyetçi-Turanî bir gelecek tasarladığı ütopik romanı hangisidir?', 'Yeni Turan', ['Raik\'in Annesi', 'Mev\'ud Hüküm', 'Kalp Ağrısı'], '1912\'de yayımlanan \'Yeni Turan\', Yeni Turan Partisi lideri Oğuz, idealist Türk kadını Kaya ve merkeziyetçi Yeni Osmanlılar lideri Hamdi Paşa arasındaki siyasi-duygusal çatışmayı gelecek zaman kurgusuyla işler.'),
  ('Sinekli Bakkal romanında kadın kılığına girerek \'zenne\' rolü oynadığı için bu lakapla anılan, Jön Türklere yardım ederken Şam\'a sürgün edilen halk sanatçısı karakter kimdir?', 'Kız Tevfik', ['Cüce Rakım', 'İmam İlhami Efendi', 'Abdülgaffar Efendi'], 'Rabia\'nın babası Kız Tevfik; Karagöz ve ortaoyunu geleneğini yaşatan, saf yürekli, fedakâr (Jön Türk Hilmi\'nin evraklarını kadın çarşafıyla taşırken yakalanan) sevimli bir halk sanatçısıdır.'),
  ('Halide Edip\'in \'Sinekli Bakkal\'da mahalle imamı Hacı İlhami Efendi ile Mevlevi şeyhi Vehbi Dede\'yi karşıt karakterler olarak kurgulaması hangi tematik ayrıma dayanır?', 'Cehennem korkusuna ve katı biçimciliğe dayalı hoşgörüsüz yobazlık ile insan sevgisine, sanata ve hoşgörüye dayalı tasavvuf irfanı arasındaki ayrıma', ['Saray bütçesinden yüksek maaş alan resmi ulema ile taşra vakıflarından geçinen yoksul medrese müderrisleri arasındaki ekonomik farka', 'Meşrutiyet anayasasını destekleyen yenilikçi din adamları ile saltanatın devamını savunan gelenekçi tarikatlar arasındaki siyasal kavgaya', 'Arapça hutbe okunmasını isteyen medreseliler ile Türkçe ibadet yapılmasını savunan Türkçü vaizler arasındaki dil tartışmasına'], 'Rabia\'nın dedesi İmam İlhami Efendi neşeyi ve müziği yasaklayan korkutucu bir bağnazlığı temsil ederken, Vehbi Dede musikiyi ve sevgiyi kutsayan engin Mevlevi hoşgörüsünü temsil eder.'),
  ('Halide Edip\'in Boğaziçi\'ndeki Poyrazköy\'de yaşayan Lale (Tatarcık) adlı modern, çalışkan Cumhuriyet genç kızının farklı dünya görüşlerindeki gençlerle kurduğu fikrî etkileşimi anlattığı romanı hangisidir?', 'Tatarcık', ['Sonsuz Panayır', 'Döner Ayna', 'Akile Hanım Sokağı'], '1939\'da yayımlanan \'Tatarcık\', Kırım göçmeni bir babanın kızı olan İngilizce öğretmeni Lale ve \'Sungur Balım\' yatıyla gelen üniversiteli gençler üzerinden yeni Cumhuriyet neslinin düşünsel yönelimlerini tartışır.'),
  ('Reşat Nuri\'nin \'Yeşil Gece\' romanında Somuncuoğlu Medresesi\'nde yetiştiği hâlde dini istismar eden yobazlığa karşı mücadele etmek için Darülmuallimin\'i bitirip Sarıova\'ya öğretmen giden idealist kahraman kimdir?', 'Şahin Efendi', ['Mürşit Efendi', 'Ali Rıza Bey', 'Vehbi Dede'], '1928 tarihli \'Yeşil Gece\'de Ali Şahin, \'yeşil gece\' diye adlandırdığı medrese karanlığını ve hurafe sömürüsünü laik, akılcı ilkokul eğitimiyle yıkmaya adanmış devrimci bir öğretmendir.'),
  ('Yeşil Gece romanının sonunda Yunan işgali bittikten sonra Sarıova\'ya dönen Şahin Öğretmen\'in karşılaştığı acı ironi aşağıdakilerden hangisidir?', 'İşgal sırasında düşmanla iş birliği yapan sarıklı softaların şapka giyip Cumhuriyetçi kesilerek kendisini Yunan işbirlikçisi diye kasabadan kovdurmaları', ['Yıllarca emek vererek yaptırdığı modern okul binasının şiddetli bir depremde yıkılıp altında öğrencilerinin kalması', 'Kasaba halkının kendisini milletvekili seçerek çok sevdiği ilkokul öğretmenliğinden zorla Ankara bürokrasisine göndermesi', 'Medreseden eski arkadaşı Rasim\'in kasabaya vali atanarak bütün laik okulları yeniden sıbyan mektebine çevirmesi'], 'Şahin Bey işgal yıllarında kasaba halkını korumak için düşmana görünürde ılımlı davranmış; ancak kurtuluştan sonra bukalemun gibi kılık değiştiren çıkarcılar onu vatan hainliğiyle suçlamıştır.'),
  ('Reşat Nuri\'nin \'Dudaktan Kalbe\' romanında Boğaziçi ve İzmir arasında geçen gurur-aşk çatışmasının kahramanları olan ünlü keman virtüözü ile tütün kızı kimlerdir?', 'Hüseyin Kenan ile Lamia', ['Kâmran ile Feride', 'İffet ile Doktor Nihat', 'Ömer Behiç ile Neyyir'], 'Saib Paşa\'nın yeğeni besteci ve kemancı Hüseyin Kenan, toplumsal mevki kaygısıyla \'Kınalı Yapıncak\' adını taktığı Lamia\'yla evlenmekten kaçınır; ancak ömür boyu süren pişmanlığı onu intihara sürükler.'),
  ('Reşat Nuri\'nin \'Miskinler Tekkesi\' romanında dilenciliği dededen kalma bir meslek ve hayat felsefesi gibi benimseyen anlatıcı kahramanın mizahi öyküsü hangi toplumsal eleştiriyi barındırır?', 'Osmanlı\'dan devralınan tevekkül maskeli tembellik, asalaklık ve üretmeden geçinme alışkanlığının keskin bir ironiyle teşhir edilmesini', ['Sanayi Devrimi sonrasında fabrikalarda işsiz kalan dokuma işçilerinin sendikal hak arayışlarının bastırılmasını', 'Cüzzamlı hastaların kapatıldığı sağlık kurumlarındaki hijyen ve ilaç yetersizliğinin belgesel biçimde raporlanmasını', 'Divan şairlerinin caize alabilmek için devlet büyüklerine abartılı kasideler sunma geleneğinin parodileştirilmesini'], '1946\'da yayımlanan \'Miskinler Tekkesi\', Sadrazam Kocabaş Kazım Paşa\'nın torunu olan doğuştan miskin kahramanın İzmir ve İstanbul\'daki dilencilik serüvenleriyle Doğu kaderci tembelliğini hicveder.'),
  ('Ebubekir Hazım Tepeyran\'ın 1910 yılında yayımlanan ve Niğde\'nin Hoşgör köyünden sekiz yaşındaki İlyas\'ın İstanbul\'a uzanan acıklı yaşamını anlatan gerçekçi köy romanı hangisidir?', 'Küçük Paşa', ['Karabibik', 'Zehra', 'Bizim Köy'], 'Nabizade Nazım\'ın \'Karabibik\'inden sonra Anadolu köyünü ve köylüsünü bürokratik gözlemlerle geniş ölçekte işleyen ilk başarılı roman Ebubekir Hazım\'ın \'Küçük Paşa\'sıdır (sonunda Salih\'i kurtlar parçalar).'),
  ('Küçük Paşa romanında sütannesi Selime\'nin bebeği Salih\'in konakta paşa çocuğu gibi el bebek gül bebek büyütüldükten sonra paşanın ölümüyle köye geri gönderilip kurtlar tarafından parçalanması neyi simgeler?', 'İstanbul konağının geçici hevesiyle doğasından koparılan Anadolu çocuğunun geri itildiği bakımsız ve sahipsiz taşra gerçekliğinde yok oluşunu', ['Kırsal bölgelerde yaban hayvanlarıyla mücadele için avcılık teşkilatlarının kurulmamasından doğan belediye ihmalini', 'Köylü kadınların çocuklarını İstanbul\'daki zengin ailelere evlatlık vererek başlık parası toplama geleneğini', 'Göçebe aşiretlerin yerleşik tarım köylerine düzenlediği kış baskınlarının yarattığı güvenlik boşluğunu'], 'Konakta \'Küçük Paşa\' diye sevilen Salih, Selime\'nin yeniden evlenmesi ve üvey babanın istememesiyle köyün sert doğasında yapayalnız kalır ve trajik biçimde can verir.'),
  ('Refik Halit Karay\'ın \'Memleket Hikâyeleri\'nde yer alan \'Şeftali Bahçeleri\' öyküsünde idealist memur Agâh Bey\'in kasabadaki memurların tembellik ve rakı âlemlerine önce direnip sonunda aynı rehavete teslim olması neyi anlatır?', 'Durağan ve üretimsiz taşra bürokrasisinin bireysel reform heveslerini yutarak kendine benzetme gücünü', ['Anadolu\'da meyvecilik ve tarımsal sulama kooperatiflerinin kurulmasıyla kasaba refahının hızla yükselmesini', 'Mülkiye mezunlarının köylülerle el ele vererek kasabada modern bir ziraat enstitüsü inşa etme başarısını', 'Sürgün memurların hükümet konağında gizli edebiyat toplantıları düzenleyerek yerel bir gazete çıkarmasını'], 'Mülkiye mezunu tahrirat müdürü Agâh Bey kasabayı kalkındırma azmiyle gelir, fakat sıcak yaz ikindilerinde \'Şeftali Bahçeleri\'nin uyuşuk keyfine yenilip o da istifa edemeyen klasik taşra memuruna dönüşür.'),
  ('Refik Halit Karay\'ın Yüz Ellilikler listesinde yurt dışına gönderildiği Beyrut ve Halep yıllarındaki gözlemlerinden doğan, eski İttihatçı yüzbaşı Hilmi Efendi\'nin gurbetteki sefaletini ve kızı Seher\'le karşılaşmasını anlatan romanı hangisidir?', 'Sürgün', ['Yezidin Kızı', 'Bugünün Saraylısı', 'İstanbul\'un İç Yüzü'], 'Refik Halit\'in 1941\'de yayımlanan \'Sürgün\' romanı, Beyrut\'a sürülen emekli yüzbaşı Hilmi Efendi\'nin gurbetteki düşkünlüğünü ve değişen insan ilişkilerini güçlü bir gerçekçilikle anlatır.'),
  ('Ömer Seyfettin\'in Bulgar komitacılarının milliyetçilik ateşini gördükten sonra Türk gençlerinde ulusal bilinç uyandırmak gereğini kavrayan genç bir Osmanlı subayının uyanışını anlattığı öyküsü hangisidir?', 'Primo Türk Çocuğu', ['Bomba', 'Beyaz Lale', 'Pembe İncili Kaftan'], 'Selanik\'te İtalyan bir kadınla evlenip kozmopolit yaşayan mühendis Kenan Bey\'in oğlu Primo\'nun Trablusgarp ve Balkan işgalleri karşısında \'Ben Türküm!\' diyerek Türklüğü seçmesi \'Primo Türk Çocuğu\'nda anlatılır.'),
  ('Ahmet Hikmet Müftüoğlu\'nun Servetifünun döneminde yazdığı süslü \'Haristan ve Gülistan\'dan sonra Millî Edebiyat döneminde sade Türkçe ve Türkçülük coşkusuyla yayımladığı hikâye kitabı ve tek romanı hangisidir?', 'Çağlayanlar - Gönül Hanım', ['Memleket Hikâyeleri - Çete', 'Milli Savaş Hikâyeleri - Yaban', 'Dağa Çıkan Kurt - Yeni Turan'], 'Ahmet Hikmet Müftüoğlu, Millî Edebiyat döneminde yalın ve destansı bir dille \'Çağlayanlar\' (\'Üzümcü\', \'Alparslan Masalı\') öykülerini ve Orhun Yazıtları\'na uzanan Turancı romanı \'Gönül Hanım\'ı (1920) yazmıştır.'),
  ('Aka Gündüz\'ün Kurtuluş Savaşı yıllarındaki Ankara atmosferinde nişanlısı pilot Murat\'ın şehit düştüğünü sanarak psikolojik sarsıntı geçiren Yıldız\'ın öyküsünü anlattığı ünlü romanı hangisidir?', 'Dikmen Yıldızı', ['İki Süngü Arasında', 'Bir Şoförün Gizli Defteri', 'Odun Kokusu'], 'Aka Gündüz\'ün 1928\'de yayımlanan popüler Millî Mücadele romanı \'Dikmen Yıldızı\', İzmirli Yıldız ile cephedeki nişanlısı Yüzbaşı Murat\'ın öyküsü etrafında Ankara\'nın direniş ruhunu yansıtır.'),
  ('Peyami Safa\'nın 1923\'te yayımlanan ilk önemli romanı \'Sözde Kızlar\'da Yunan işgali altındaki Manisa\'dan babasını aramak için İstanbul\'a gelen Mebrure hangi yozlaşmış çevreyle karşılaşır?', 'Nafi Bey\'in Şişli\'deki konağında Behiç gibi ahlaksız züppelerin kurduğu \'Çılgınlar Kulübü\' ve sahte Batılılaşmış sosyete çevresiyle', ['Beyazıt sahaflar çarşısında eski el yazmalarını yabancılara satan gizli bir kaçakçılık şebekesiyle', 'Galata\'da müttefik donanma askerlerine sahte pasaport düzenleyen Levanten banker aileleriyle', 'Kadıköy\'de tiyatro kumpanyası kurma vaadiyle taşralı gençleri dolandıran gezgin oyuncularla'], 'Peyami Safa \'Sözde Kızlar\'da Anadolu\'nun temiz ve dürüst kızı Mebrure\'yi, Mütareke İstanbul\'unun kokain, kumar ve gayrimeşru ilişkilerle çürümüş Şişli sosyetesi (Behiç, Nevin, Belma) karşısına çıkarır.'),
  ('Mithat Cemal Kuntay\'ın II. Abdülhamit istibdadı, II. Meşrutiyet ve Mütareke olmak üzere üç tarihsel dönemin çöküşünü avukat ve yazar Adnan\'ın yükseliş-düşüş öyküsü etrafında anlattığı dev romanı hangisidir?', 'Üç İstanbul', ['Sodom ve Gomore', 'Kiralık Konak', 'İstanbul\'un İç Yüzü'], '1938\'de yayımlanan \'Üç İstanbul\', yoksul edebiyat öğretmeni Adnan\'ın Süheyla ve Belkıs arasındaki ikilemleri ve İttihat-Terakki nüfuzuyla yozlaşması üzerinden İmparatorluğun son kırk yılını sergiler.'),
  ('Halide Edip Adıvar\'ın 1919\'da yayımladığı ve İzmir\'in işgali sonrasında Anadolu insanının işgalcilere karşı verdiği trajik ve destansı direnişi öyküleştirdiği kitabının adı nedir?', 'Dağa Çıkan Kurt', ['Harap Mabetler', 'Kubbede Kalan Hoş Sada', 'Kenan Çobanları'], 'Halide Edip ilk dönem bireysel hikâyelerini \'Harap Mabetler\'de (1911), Kurtuluş Savaşı ve işgal yıllarındaki millî uyanış hikâyelerini ise \'Dağa Çıkan Kurt\'ta (1922) toplamıştır.'),
  ('Yakup Kadri Karaosmanoğlu\'nun Kurtuluş Savaşı yıllarında Tetkik-i Mezalim Heyeti üyesi olarak Batı Anadolu\'da tanık olduğu işgal vahşetini ve halkın direncini anlattığı öykü kitabı hangisidir?', 'Milli Savaş Hikâyeleri', ['Bir Serencam', 'Rahmet', 'Erenlerin Bağından'], 'Yakup Kadri\'nin Fecriati etkisindeki ilk kitabı \'Bir Serencam\' (1913), Millî Edebiyat geçişi \'Rahmet\' (1923), Kurtuluş Savaşı gözlemlerini bir araya getiren kitabı ise \'Milli Savaş Hikâyeleri\'dir (1947).'),
  ('Namık Kemal\'in Renan\'ın \'İslamiyet terakkiye (bilime ve ilerlemeye) manidir\' iddiasını tarihsel ve akılcı kanıtlarla çürütmek amacıyla Midilli\'de kaleme aldığı savunma eseri hangisidir?', 'Renan Müdafaanamesi', ['Tahrib-i Harabat', 'İntibah Mukaddimesi', 'Bârika-i Zafer'], 'Fransız düşünür Ernest Renan\'ın 1883\'te Sorbonne\'da verdiği konferansta İslam\'ı bilime düşman göstermesi üzerine Namık Kemal \'Renan Müdafaanamesi\'ni yazarak İslam uygarlığının bilime katkılarını savunmuştur.'),
  ('Cenap Şahabettin\'in Servet-i Fünun dergisinde \'saat-i semen-fam\' (yasemin renkli saatler) ve \'nay-ı zümürrüd\' (zümrüt ney) gibi alışılmamış bağdaştırmalar kullanması devrin basınında neden büyük alay ve tartışma konusu olmuştur?', 'Geleneksel belagat kurallarına aykırı biçimde soyut zaman kavramına renk ve koku yükleyen sembolist duyular arası aktarma (sinestezi) tekniğini ilk kez denemesi yüzünden', ['Fransızcadan bire bir sözlük çevirisi yaparken \'saat\' kelimesinin Arapça müennes (dişil) yapısını dil bilgisi açısından yanlış çekimlemesi yüzünden', 'Divan şairi Şeyh Galip\'in Hüsn ü Aşk mesnevisindeki beyitleri hiçbir değişiklik yapmadan kendi imzasıyla yayımlaması yüzünden', 'Saray saatçibaşısının padişaha hediye ettiği mücevherli saati hicvederek siyasi sansür kurallarını ihlal etmesi yüzünden'], 'Fransız sembolistlerinden etkilenen Cenap Şahabettin, alışılmamış imgeler ve sinestezi (duyular arası aktarım) teknikleriyle eski edebiyat yanlılarının (\'Tımarhane edebiyatı\' suçlamalarının) şimşeklerini üzerine çekmiştir.'),
  ('1918 yılında Ruşen Eşref Ünaydın\'ın devrin önde gelen on sekiz şair, yazar ve düşünürüyle dil, vezin ve Millî Edebiyat üzerine yaptığı kapsamlı mülakatları topladığı belgesel eserin adı nedir?', 'Diyorlar ki', ['Edebiyatçılarımız Konuşuyor', 'Geçmiş Zaman Köşkleri', 'Kendi Gök Kubbemiz'], 'Ruşen Eşref\'in \'Diyorlar ki\' (1918) eseri; Abdülhak Hamit\'ten Halit Ziya\'ya, Cenap Şahabettin\'den Ziya Gökalp ve Ömer Seyfettin\'e uzanan mülakatlarıyla dönemin bütün edebi tartışmalarının canlı bilançosudur.'),
  ('Mehmet Akif Ersoy ile Tevfik Fikret arasında II. Meşrutiyet yıllarında \'Tarih-i Kadim\' ve \'Molla Sırat\' üzerinden patlak veren sert kalem kavgasının temel ekseni nedir?', 'Tevfik Fikret\'in pozitivist ve din dışı insancıl (hümanist-materyalist) tarih görüşü ile Mehmet Akif\'in İslamcı ahlak ve iman merkezli medeniyet anlayışı arasındaki çatışma', ['Aruz ölçüsünün Türkçenin ses yapısına uyarlanmasında İstanbul ağzının mı yoksa Kahire ağzının mı esas alınacağı tartışması', 'Darülfünun edebiyat fakültesinde Fransızca derslerinin kaldırılıp yerine Arap ve Fars edebiyatı kürsülerinin kurulması meselesi', 'Balkan Savaşı sırasında toplanan Kızılay yardımlarının cephe hastanelerine dağıtımında izlenecek mali denetim yöntemi'], 'Fikret\'in \'Tarih-i Kadim\'de dinleri savaş ve baskı kaynağı göstermesi üzerine Akif onu \'Zangoçluk\'la suçlamış, Fikret de \'Tarih-i Kadim\'e Zeyl\' ile Akif\'e \'Molla Sırat\' diyerek karşılık vermiştir.'),
  ('Mizancı Murat\'ın 1890\'da yayımlanan \'Turfanda mı Yoksa Turfa mı?\' romanında Cezayir\'den İstanbul\'a gelen idealist Doktor Mansur Bey\'in Bâbıâli memuriyetinde ve Anadolu\'da yapmak istediği reformlar hangi anlayışın öncüsüdür?', 'Tanzimat\'tan Millî Edebiyat\'a uzanan idealist, ahlakçı ve köycü-kalkınmacı aydın tezinin', ['Servetifünun sanatçılarının dış dünyadan kaçarak Yeni Zelanda\'da bireysel çiftlik kurma hayalinin', 'Fecriati şairlerinin siyasetten tamamen uzak durup saf sembolist müzik estetiği yaratma çabasının', 'Natüralist yazarların kalıtımsal akıl hastalıklarını klinik deneylerle kanıtlama yönteminin'], 'Doktor Mansur Bey, memur dairelerindeki tembellik ve rüşvetle savaşıp Anadolu\'da okul ve dispanser açma ülküsüyle Reşat Nuri ve Halide Edip\'in idealist Cumhuriyet aydınlarının erken habercisi olmuştur.'),
  ('İlk Türk kadın romancısı kabul edilen Fatma Aliye Hanım\'ın kendi imzasıyla yayımladığı ilk roman olan \'Muhadarat\'ta üvey anne baskısıyla mutsuz bir evliliğe sürüklenen Fazıla hangi temel görüşü kanıtlamak üzere kurgulanmıştır?', 'Kadının ilk aşkını unutamayacağı önyargısının yanlış olduğu ve onurlu bir kadının yeniden sevebileceği düşüncesini', ['Yabancı mürebbiyelerle büyüyen konak kızlarının geleneksel el işlerini öğrenemeyeceği iddiasını', 'Görücü usulüyle yapılan bütün evliliklerin ilk yıldan boşanmayla sonuçlanacağı varsayımını', 'Kadınların tıp ve mühendislik dışındaki edebi mesleklerde başarılı olamayacağı görüşünü'], '1892\'de yayımlanan \'Muhadarat\'ta Fazıla, Mukaddem\'i sevmek zorunda olmadığını ve Beyrut\'ta köle olarak satıldığı evde Şefik\'le gerçek mutluluğu bulabileceğini göstererek döneminin kadın algısını sorgular.'),
  ('Servetifünun kuşağının popüler yazarlarından Saffet Nezihi\'nin genç okurları derinden etkileyen ve iki kadın (eşi Müzehher ile sevdiği Meliha) arasında bocalayan duyarlı kahramanı anlattığı ünlü romanı hangisidir?', 'Zavallı Necdet', ['Eylül', 'Kırık Hayatlar', 'Bir Ölünün Defteri'], 'Saffet Nezihi\'nin 1900\'de yayımlanan \'Zavallı Necdet\' romanı, Servetifünun\'un melankolik ve kararsız aşk duyarlılığını geniş halk kitlelerine ulaştıran en popüler eserlerden biri olmuştur.'),
  ('Mehmet Rauf\'un \'Genç Kız Kalbi\' romanında İzmir\'den İstanbul\'a gelen edebiyat meraklısı Pervin\'in hayran olduğu şair Mehmet Behiç\'in gerçekte sığ ve çıkarcı olduğunu görünce yaşadığı düş kırıklığı neyi eleştirir?', 'İstanbul salon çevrelerinin yapaylığını ve yazarların eserlerindeki yüce duygularla gerçek kişilikleri arasındaki uçurumu', ['Taşrada basılan edebiyat dergilerinin İstanbul matbaaları tarafından haksız rekabetle engellenmesini', 'Kadın şairlerin takma erkek isimleri kullanmadan şiir kitaplarını yayımlayamamalarını', 'Aruz ölçüsüyle yazılan aşk şiirlerinin genç kızları ev işlerinden soğuttuğu yönündeki muhafazakâr görüşü'], 'Pervin\'in günlüğü biçiminde yazılan \'Genç Kız Kalbi\' (1912), İzmir\'in sağlıklı doğallığı karşısında İstanbul edebiyat sosyetesinin sahteliğini gözler önüne serer.'),
  ('Hüseyin Rahmi\'nin Émile Zola natüralizmini Osmanlı konağına uyguladığı \'Mürebbiye\' romanında Parisli hafifmeşrep Matmazel Anjel hangi konağın erkeklerini birbirine düşürür?', 'Emekli bürokrat Dehri Efendi\'nin konağında Dehri Efendi, kardeşi Amca Bey, oğlu Şemi ve damadı Sadri\'yi', ['Naim Efendi\'nin Cihangir konağında Servet Bey, Cemil ve şair Hakkı Celis\'i', 'Adnan Bey\'in Boğaziçi yalısında Behlül, Süleyman Efendi ve Beşir\'i', 'Kasım Efendi\'nin Erenköy köşkünde Meftun Bey, Mahir ve Raci\'yi'], '1899\'da yayımlanan \'Mürebbiye\', çocukları eğitmesi için hiçbir geçmiş araştırması yapılmadan konağa alınan Matmazel Anjel\'in üç kuşak erkeği dolapta yakalattığı skandalla biter.'),
  ('1895-1908 yılları arasında kesintisiz 600\'ü aşkın sayı yayımlanarak Fatma Aliye, Makbule Leman, Şair Nigâr ve Güzide Sabri gibi kadın yazarların yetiştiği en uzun ömürlü Osmanlı kadın yayını hangisidir?', 'Hanımlara Mahsus Gazete', ['Genç Kadın', 'Türk Kadını', 'Aile Mecmuası'], 'İbnülhak Mehmet Tahir imtiyazında ve Fatma Şadiye Hanım yönetiminde 13 yıl çıkan \'Hanımlara Mahsus Gazete\', Osmanlı kadın edebiyatının en verimli okulu olmuştur.'),
  ('II. Meşrutiyet döneminde Salah Cimcoz ve Celal Esat Arseven tarafından Türkçe-Fransızca çıkarılan, Refik Halit Karay\'ın \'Kirpi\' takma adıyla ilk siyasi taşlamalarını yayımladığı modern mizah dergisi hangisidir?', 'Kalem', ['Çıngıraklı Tatar', 'Hayal', 'Latife'], '1908-1911 arasında çıkan \'Kalem\' dergisi, Cemil Cem\'in karikatürleri ve Refik Halit\'in (\'Kirpi\'nin Dedikleri\') mizah yazılarıyla modern Türk mizah dergiciliğinin öncüsü olmuştur.'),
  ('Refik Halit Karay\'ın Mütareke\'nin son yılında (1922) İstanbul\'da tek başına çıkardığı ve Anadolu\'daki Millî Mücadele aleyhindeki mizahi yazıları yüzünden Yüz Ellilikler listesine alınmasına yol açan dergi hangisidir?', 'Aydede', ['Güleryüz', 'Akbaba', 'Zümrüdüanka'], 'Refik Halit\'in 1922\'de çıkardığı \'Aydede\' mizah dergisi edebi bakımdan çok güçlü kadrolar barındırsa da Ankara Hükümeti\'ne muhalif tutumu nedeniyle yazarın sürgününe sebep olmuştur.'),
  ('1918-1919 yıllarında Yusuf Ziya Ortaç tarafından çıkarılan ve Beş Hececiler başta olmak üzere genç kuşak hececi şairlerin ürünlerini bir araya getiren haftalık şiir dergisi hangisidir?', 'Şair', ['Meşale', 'Varlık', 'Yaprak'], 'Yusuf Ziya Ortaç\'ın çıkardığı \'Şair\' mecmuası ve Halit Fahri\'nin çıkardığı \'Nedim\' dergisi, Mütareke yıllarında hece ölçüsüyle yazılan memleketçi-romantik şiirin yaygınlaşmasını sağlamıştır.'),
  ('1915 yılında Fuat Köprülü ve Ziya Gökalp öncülüğünde yayımlanan, Türk edebiyatı tarihi, sosyolojisi ve halk kültürü üzerine bilimsel-akademik araştırmalara yer veren dergi hangisidir?', 'Millî Tetebbular Mecmuası', ['Hüsn ü Şiir', 'Çocuk Bahçesi', 'Servet-i Fünun'], 'Beş sayı yayımlanan \'Millî Tetebbular Mecmuası\', Fuat Köprülü\'nün modern edebiyat tarihçiliği yöntemini uyguladığı kapsamlı bilimsel incelemeleriyle Türkoloji araştırmalarında dönüm noktası olmuştur.'),
  ('Ahmet Haşim\'in 1921\'de Akşam gazetesinde yayımlanan ve \'Piyale\' kitabının başına \'Şiir Hakkında Bazı Mülahazalar\' adıyla alınan poetik yazısı hangi tartışmanın sonucunda kaleme alınmıştır?', '\'Bir Günün Sonunda Arzu\' şiirinin anlaşılmaz ve kapalı bulunarak alaya alınması üzerine başlayan \'şiirde anlam ve açıklık\' tartışmasının', ['Hece ölçüsünün on birli ve on dörtlü kalıplarında durak yerlerinin kaldırılıp kaldırılmayacağı tartışmasının', 'Tiyatro oyunlarının manzum mu yoksa mensur mu yazılması gerektiğine ilişkin Darülbedayi polemiğinin', 'Divan şiirindeki gazel biçiminin Cumhuriyet döneminde yasaklanmasını isteyen genç şairlerin bildirisinin'], 'Haşim\'in Dergâh\'ta çıkan \'Bir Günün Sonunda Arzu\' şiiri (\'Akşam, yine akşam, yine akşam...\') anlaşılmaz bulunup eleştirilince Haşim \'Şiirde Mânâ ve Vuzuh\' makalesini yazarak şiirin sözden ziyade musikiye yakın olduğunu savunmuştur.'),
  ('Namık Kemal\'in ilk tarihsel romanımız sayılan \'Cezmi\' (1880) eserinde 16. yüzyıl Osmanlı-İran savaşları fonunda şair ve sipahi Cezmi hangi Kırım şehzadesiyle kader birliği yapar?', 'İran\'a esir düşen ve Şah\'ın karısı Şehriyar ile kız kardeşi Perihan\'ın aşkı arasında kalan Adil Giray ile', ['Viyana kuşatmasında akıncı kolunu yöneten Kırım Hanı Kırım Giray ile', 'Mohaç Meydan Muharebesi\'nde sancak taşıyan Malkoçoğlu Bali Bey ile', 'Bağdat seferinde kale burçlarına ilk bayrağı diken Genç Osman ile'], 'Cezmi romanında ideal Osmanlı askeri Cezmi ile Kırım şehzadesi Adil Giray, İran sarayında Perihan\'ın Sünni yönetimi kurma planı ve Şehriyar\'ın kıskançlık entrikaları arasında trajik sonla yüzleşir.'),
  ('Sergüzeşt romanında Mısır\'daki konakta harem ağası Cevher Ağa\'nın kendi canını feda ederek Dilber\'i üst kat penceresinden kaçırmaya çalışması esere hangi insani derinliği katar?', 'Kölelik kurumunun ezdiği bir başka tutsak olan harem ağasının yüksek şefkat ve özgürlük dayanışması göstermesini', ['Mısır\'daki köle tüccarlarının İstanbul\'daki rakiplerinden intikam almak için düzenlediği ticari komployu', 'Cevher Ağa\'nın Dilber\'i kaçırıp yüksek fidye karşılığında Asaf Paşa ailesine geri satma planını', 'İngiliz konsolosluk görevlilerinin esir ticaretini denetlemek üzere saraya sızma girişimini'], 'Dış görünüşü çirkin ama yüreği son derece merhametli olan harem ağası Cevher, Dilber\'i kurtarmak için ip merdivenden inerken düşüp ölür; bu sahne Hugo romantizmi ile gerçekçiliğin birleşimidir.'),
  ('Nabizade Nazım\'ın \'Zehra\' (1896) romanında babası Şevket Efendi\'nin kâtibi Suphi ile evlenen Zehra\'nın hastalıklı kıskançlığı hangi yıkımlar zincirine yol açar?', 'Suphi\'nin cariye Sırrıcemal\'le evlenmesine, Zehra\'nın intikam için tuttuğu Rum yosması Ürani\'nin Suphi\'yi iflas ettirip katil yapmasına ve Sırrıcemal ile Zehra\'nın ölümlerine', ['Suphi\'nin ticarethaneyi kapatıp Zehra\'yla birlikte İsviçre\'deki bir ruh sağlığı kliniğine yerleşmesine ve orada iyileşmesine', 'Zehra\'nın kıskançlık krizleri sırasında konağı ateşe vererek babası Şevket Efendi\'yle birlikte yangında can vermesine', 'Sırrıcemal\'in Suphi\'den doğan çocuğunu kaçırarak Mısır\'daki zengin akrabalarının yanına sığınmasına'], 'İlk psikolojik roman denemesi ve natüralist tezli roman sayılan \'Zehra\', çocukluğundan beri aşırı kıskanç mizaca sahip Zehra\'nın intikam hırsıyla hem sevdiği Suphi\'yi hem masum Sırrıcemal\'i hem kendini yok etmesini işler.'),
  ('Tanzimat\'tan Cumhuriyet\'e edebî tartışmaların gelişim çizgisi incelendiğinde, tartışma konularının hangi doğrultuda evrildiği görülür?', 'Kafiye ve belagat kurallarından (eski-yeni) başlayıp sanatın bireyselliği-toplumsallığı üzerinden ulusal dil, hece ölçüsü ve Anadolu gerçekliğine doğru', ['Serbest nazım ve toplumcu gerçekçilikten başlayıp divan mazmunlarının ve aruz kalıplarının yeniden canlandırılmasına doğru', 'Roman ve tiyatro tekniği tartışmalarından başlayıp bütün edebi türlerin bırakılarak yalnızca tarih yazıcılığı yapılmasına doğru', 'Latin alfabesi ve öztürkçecilikten başlayıp Osmanlıca üç dilli terkip sisteminin resmi eğitim dili yapılmasına doğru'], 'Harabat-Tahrib-i Harabat ve Zemzeme-Demdeme ile başlayan biçim/kafiye tartışmaları, Dekadanlar\'la üslup ve anlam boyutuna, Genç Kalemler ve Dergâh ile de ulusal dil ve memleket edebiyatı zeminine evrilmiştir.'),
  ('Ziya Gökalp\'in Genç Kalemler\'den sonra şiir, masal ve makaleleriyle hem çocuklara hem halka ulaşmak için 1913\'te çıkardığı \'Halka Doğru\' ve \'Türk Sözü\' dergilerinin temel yayın ilkesi nedir?', 'Aydınların seçkinci kulesinden inerek halkın yaşayan dilini, masallarını ve folklorunu öğrenip halkı çağdaş uygarlıkla buluşturması', ['Yalnızca Darülfünun profesörlerinin anlayabileceği yüksek sosyoloji ve felsefe terimlerini Arapça köklerden türetmesi', 'Halk edebiyatı ürünlerini basılı kitap hâline getirmeden yalnızca sözlü gelenekte tutarak doğallığını koruması', 'Balkan dillerinden çevrilen popüler aşk romanlarını ücretsiz ek olarak dağıtarak okuma oranını artırması'], 'Türk Yurdu\'nun kardeş yayınları olan \'Halka Doğru\' (Halide Edip, Fuat Köprülü, Akçura, Gökalp) ve Ömer Seyfettin\'in başyazarlığını yaptığı \'Türk Sözü\', Gökalp\'in \'halka doğru gitmek: halka medeniyet götürüp halktan hars almak\' ilkesini uygulamıştır.'),
  ('Yakup Kadri\'nin \'Kiralık Konak\', \'Hüküm Gecesi\', \'Sodom ve Gomore\', \'Yaban\', \'Ankara\' ve \'Panorama\' romanlarını birbirine bağlayan üst edebi yapı nasıl adlandırılır?', 'Tanzimat\'tan Cumhuriyet\'in çok partili yıllarına dek Türk toplumunun tarihsel dönüşümünü izleyen \'devir / nehir roman\' zinciri', ['Aynı dedektif kahramanın farklı şehirlerdeki cinayetleri çözdüğü seri polisiye macera dizisi', 'Doğaüstü masal kahramanlarının her yüzyılda yeniden dünyaya gelişini anlatan fantastik mitoloji külliyatı', 'Yazarın yalnızca kendi çocukluk ve okul anılarını kronolojik sırayla aktardığı otobiyografik günlük dizisi'], 'Yakup Kadri, Balzac ve Zola geleneğine benzer biçimde İmparatorluğun çöküşünden Cumhuriyet\'in kuruluş ve yerleşmesine kadar her tarihsel döneme bir roman ayırarak bütünlüklü bir \'devir/nehir roman\' panoraması kurmuştur.'),
  ('Halide Edip Adıvar, Yakup Kadri Karaosmanoğlu ve Reşat Nuri Güntekin\'in Millî Edebiyat dönemi romanlarında \'yobaz din adamı\' (Hacı Fettah, Şeyh Yusuf, Sarıovalı softalar) tipini ortaklaşa eleştirmelerinin tarihsel nedeni nedir?', 'Millî Mücadele ve çağdaşlaşma hamlesine karşı işgalcilerle iş birliği yapan ve dini kişisel çıkar aracı kılan bağnazlığın toplumsal uyanışı engellemesi', ['Üç yazarın da din ve tasavvuf kültürünün her türlüsünü edebi metinlerden tamamen silmek üzere ortak manifesto imzalaması', 'Osmanlı tarihinde hiçbir medrese veya tekke mensubunun Kurtuluş Savaşı\'na destek vermemiş olması', 'Fransızcadan uyarladıkları roman şablonlarında yer alan Katolik papaz tiplerini isimlerini değiştirerek aynen aktarmaları'], 'Halide Edip \'Sinekli Bakkal\'da Vehbi Dede gibi gerçek mutasavvıfları yüceltirken \'Vurun Kahpeye\'de Hacı Fettah\'ı; Yakup Kadri Şeyh Yusuf\'u; Reşat Nuri de \'Yeşil Gece\'de çıkarcı softaları eleştirerek samimi inanç ile din istismarını ayırmıştır.'),
  ('Ömer Seyfettin\'in \'Yalnız Efe\' adlı uzun öyküsünde tefeci Eseoğlu\'nun babasını öldürtmesi ve devlet kapısında hakkını arayamaması üzerine silaha sarılıp dağa çıkan genç kız kahraman kimdir?', 'Kezban', ['Emine', 'Zeynep', 'Elif'], 'Anadolu halkının zulme karşı direniş ruhunu simgeleyen Kezban, Yörük Hoca\'nın katili tefeci Eseoğlu\'ndan öcünü almak üzere erkek kılığında dağa çıkar ve mazlum köylülerin koruyucusu \'Yalnız Efe\' efsanesine dönüşür.'),
  ('Reşat Nuri Güntekin\'in \'Damga\' romanında ağabeyinin mirasını korumak ve sevdiği Vedia\'nın onurunu kurtarmak için işlemediği hırsızlık suçunu üstlenerek ömür boyu \'hırsız\' damgası taşıyan fedakâr kahraman kimdir?', 'İffet', ['Şevket', 'Kâmran', 'Hüseyin Kenan'], '1924\'te yayımlanan \'Damga\'da paşa oğlu İffet, evli Vedia\'nın gece yarısı odasından çıkarken yakalandığında kadının namusunu kurtarmak için \'Ben hırsızlık yapmaya geldim\' der ve toplumun acımasız damgasını ömür boyu taşır.'),
  ('Reşat Nuri Güntekin\'in \'Kızılcık Dalları\' romanında Nadide Hanım\'ın konağına küçük yaşta besleme (evlatlık) olarak alınan Gülsüm\'ün yaşadığı acıklı hayat hangi konak gerçeğini eleştirir?', 'Hayır işleme görüntüsü altında küçük kız çocuklarının konaklarda şefkatsiz, güvencesiz ve ücretsiz köle gibi çalıştırılıp sokağa atılmasını', ['Konak bahçelerindeki meyve ağaçlarının bakımsızlıktan kurumasıyla geleneksel İstanbul bahçe kültürünün yok olmasını', 'Varlıklı ailelerin öz çocuklarını yatılı Avrupa okullarına göndererek aile bağlarını zayıflatmasını', 'Emekli paşaların konaklarını apartman müteahhitlerine satarak kira gelirleriyle geçinmeye başlamasını'], '1932 tarihli \'Kızılcık Dalları\', \'yüz verince tepemize çıkar\' denilerek kızılcık sopasıyla dövülen besleme kız Gülsüm ve dilsiz İsmail\'in konaktaki sömürüsünü keskin bir vicdan muhasebesiyle işler.'),
  ('Reşat Nuri Güntekin\'in \'Değirmen\' (1944) romanında Sarıpınar kasabası kaymakamı Halil Hilmi Efendi ve memurların sarhoşluk gecesinde yaşanan küçük bir sarsıntıyı \'büyük deprem felaketi\' diye Ankara\'ya bildirmeleri neyin taşlamasıdır?', 'Bürokratik korku, iletişimsizlik ve koltuk koruma telaşının yoktan ulusal bir felaket uyduracak kadar absürt boyutlara ulaşmasının', ['Anadolu fay hatları üzerinde ahşap yerine kerpiç binalar yapılmasının yol açtığı gerçek imar facialarının', 'Yabancı yardım kuruluşlarının deprem bahanesiyle maden sahalarında izinsiz harita çalışması yapmasının', 'Kasaba eşrafının devletten kredi alabilmek için tarihi su değirmenlerini kasten yıkmasının'], 'Gogol\'ün \'Müfettiş\'ini andıran \'Değirmen\'de, merkeze çekilen abartılı telgraf sonrası Kızılhaç ve müfettişler gelince memurlar yalanları ortaya çıkmasın diye sağlam binaları bizzat yıkmak zorunda kalır!'),
  ('Halide Edip Adıvar\'ın 1910\'da yayımlanan \'Seviyye Talip\' romanında kocasını terk ederek sevdiği müzisyen Cemal\'le nikâhsız yaşamayı göze alan Seviyye ve ona tutulan evli Fahri\'nin öyküsü Meşrutiyet basınında neden tepki çekmiştir?', 'Kadının kendi duygusal ve bireysel iradesini geleneksel nikâh ve toplum kurallarının üstünde tutan cüretkâr bir kadın portresi çizdiği için', ['Romanın tamamında Türkçe cümle yapısını bozacak ölçüde İngilizce ve Fransızca diyaloglar kullanıldığı için', 'Balkan Savaşı öncesinde ordudaki subayların siyasetle uğraşmasını açıkça teşvik eden bildiriler içerdiği için', 'Osmanlı sarayındaki valide sultanların özel hayatlarına dair devlet sırlarını ifşa ettiği için'], 'Halide Edip\'in ilk dönem kadın psikolojisi romanlarından \'Seviyye Talip\' (ve \'Raik\'in Annesi\'), kadının bireyleşme ve aşk seçimi konusundaki alışılmadık cesaretiyle muhafazakâr eleştirmenlerin tepkisini çekmiştir.'),
  ('Tanzimat döneminde (1875) Namık Kemal, Ziya Paşa ve Sadullah Paşa gibi isimlerden bağımsız olarak Ebüzziya Tevfik\'in çıkardığı ve devrin en seçkin edebiyat-kültür seçkilerinden sayılan uzun ömürlü dergi hangisidir?', 'Mecmua-i Ebüzziya', ['Hazine-i Evrak', 'Çocuk Bahçesi', 'Genç Kalemler'], 'Ünlü matbaacı ve yazar Ebüzziya Tevfik\'in 1880\'de başlatıp Rodos sürgünü arası dışında 1912\'ye dek sürdürdüğü \'Mecmua-i Ebüzziya\', yüksek baskı kalitesi ve ansiklopedik edebiyat yazılarıyla ünlüdür.'),
  ('Türk edebiyatında ilk kez \'Millî Edebiyat\' terimini bugünkü ulusal dil ve kültür anlamıyla Genç Kalemler dergisindeki makalelerinde kuramsallaştırıp yaygınlaştıran yazar kimdir?', 'Ali Canip Yöntem', ['Ahmet Haşim', 'Süleyman Nazif', 'Recaizade Mahmut Ekrem'], 'Ömer Seyfettin \'Yeni Lisan\' terimini öne çıkarırken, Genç Kalemler\'de \'Millî Daha Doğrusu Kavmî Edebiyat Ne Demektir?\' başlıklı yazılarıyla \'Millî Edebiyat\' kavramını edebi terim olarak yerleştiren Ali Canip Yöntem olmuştur.'),
  ('Fuat Köprülü\'nün önceleri Fecriati üyesi olarak \'Milli edebiyat olamaz, sanat evrensel ve bireyseldir\' görüşünü savunurken, birkaç yıl içinde Türk edebiyatı tarihinin en büyük milliyetçi kuramcısına dönüşmesinde kimin fikrî etkisi belirleyici olmuştur?', 'Ziya Gökalp\'in Selanik\'ten İstanbul\'a taşıdığı sosyoloji ve kültür (hars) kuramının', ['Tevfik Fikret\'in Aşiyan\'da verdiği bireysel hümanizm ve kozmopolitizm derslerinin', 'Cenap Şahabettin\'in Servet-i Fünun\'daki Fransız sembolizmi ve aruz incelemelerinin', 'Abdullah Cevdet\'in İçtihat dergisindeki biyolojik materyalizm çevirilerinin'], 'Gençliğinde Genç Kalemler\'e bile karşı çıkan Fuat Köprülü, Ziya Gökalp\'le tanıştıktan sonra \'Türk Edebiyatında İlk Mutasavvıflar\' ve \'Türk Edebiyatı Tarihi\'ni yazarak Millî Edebiyat biliminin kurucusu olmuştur.'),
  ('Yahya Kemal Beyatlı\'nın \'Türkçe ağzımda annemin ak sütüdür\' anlayışıyla \'Beyaz Lisan\' adını verdiği şiir dili görüşünün Genç Kalemler\'in \'Yeni Lisan\' hareketinden ayrılan yönü nedir?', 'Sade ve doğal İstanbul Türkçesini heceyle değil, Türkçenin ses mimarisine kusursuzca uydurulmuş aruz ölçüsü ve klasik musiki disipliniyle birleştirmesi', ['İstanbul konuşma dilini tamamen reddederek Karacaoğlan ve Dadaloğlu\'nun Toros Türkmen ağzını şiir dili yapması', 'Şiirde vezin ve kafiyeyi bütünüyle kaldırıp konuşma dilindeki günlük sokak argosunu serbest nazma taşıması', 'Farsça üçlü ve dörtlü zincirleme isim tamlamalarını Servetifünun şairlerinden daha yoğun biçimde yeniden kullanması'], 'Yahya Kemal (\'Ok\' şiiri hariç) aruzu bırakmamış, ancak Cenap ve Fikret\'in yapay sözlük dilini reddederek konuşulan duru İstanbul Türkçesini (\'Beyaz Lisan\') klasik aruz ahengine dökmüştür.'),
  ('Yakup Kadri Karaosmanoğlu ile Ahmet Haşim\'in ortak estetik yönü olan ve Fecriati yıllarından kalan \'nesir-şiir üslupçuluğu\' Yakup Kadri\'nin hangi mensur şiir kitaplarında en belirgin biçimde görülür?', 'Erenlerin Bağından ve Okun Ucundan', ['Siyah İnciler ve Mezardan Sesler', 'Haristan ve Gülistan ile Çağlayanlar', 'Bize Göre ve Gurebahane-i Laklakan'], 'Yakup Kadri, Tevrat ve Yunus Emre/Mevlana mistisizmiyle Akdeniz-Yunan (Nev-Yunanilik) üslubunu harmanladığı \'Erenlerin Bağından\' ve \'Okun Ucundan\' adlı mensur şiirlerinde yüksek bir sanat nesri kurmuştur.'),
  ('Halit Ziya\'nın \'Aşk-ı Memnu\' romanında Bihter\'in annesi Firdevs Hanım\'ın (\'Melih Bey Takımı\' diye anılan ailenin) romandaki psikolojik ve determinist işlevi nedir?', 'Realizm ve natüralizmin \'soyaçekim\' (irsiyet) ilkesi uyarınca Bihter\'in sadakatsizliğe ve gösteriş tutkusuna sürüklenişini hazırlayan kalıtımsal kök olması', ['Geleneksel Osmanlı annesinin fedakâr şefkatini temsil ederek kızlarını yanlış evliliklerden korumaya çalışması', 'Nihal\'in eğitimini üstlenerek Fransız mürebbiye Matmazel de Courton\'un yalıdaki etkisini olumlu yönde dengelemesi', 'Adnan Bey\'in ticari yatırımlarını yöneterek ailenin ekonomik krizden yara almadan çıkmasını sağlaması'], 'Bihter ömrü boyunca annesi Firdevs Hanım gibi hafifmeşrep olmamaya yemin etse de Taine ve Zola determinizmi gereği kanındaki \'Melih Bey takımı\' mirasına yenik düşer.'),
  ('Hüseyin Rahmi Gürpınar ile Halit Ziya Uşaklıgil arasında II. Meşrutiyet sonrasında da dolaylı biçimde süren roman anlayışı farkının temelinde hangi karşıtlık yatar?', 'Halit Ziya\'nın seçkin zümreye seslenen kusursuz teknikli estetik-aristokrat romanı ile Hüseyin Rahmi\'nin sokağın her katmanını kucaklayan eğitici-popüler mahalle gerçekçiliği', ['Halit Ziya\'nın hece ölçülü manzum romanlar yazması ile Hüseyin Rahmi\'nin yalnızca tek perdelik köy seyirlik oyunları yazması', 'Halit Ziya\'nın tarihsel savaş romanlarını savunması ile Hüseyin Rahmi\'nin sembolist mensur şiirleri savunması', 'Halit Ziya\'nın yalın halk Türkçesi kullanması ile Hüseyin Rahmi\'nin ağır Farsça zincirleme tamlamalarla yazması'], 'Halit Ziya Türk romanına Batılı estetik kurgu ve üslup disiplinini kazandırırken, Hüseyin Rahmi romanı salonlardan çıkarıp İstanbul mahallelerinin canlı insan hazinesiyle buluşturmuştur.'),
  ('1911 yılında Genç Kalemler\'de \'Yeni Lisan\' hareketi başladığında Yakup Kadri, Fuat Köprülü, Refik Halit ve Halide Edip gibi yazarların başlangıçta çekimser kalıp 1912-1913 sonrasında bu çizgiye katılmalarını hızlandıran tarihsel kırılma nedir?', 'Trablusgarp ve özellikle Balkan Savaşları\'ndaki ağır toprak kayıplarının imparatorluk kozmopolitizmini yıkıp ulusal uyanışı zorunlu kılması', ['Servetifünun yazarlarının mahkeme kararıyla genç yazarların ağır tamlamalar kullanmasını telif hakkı gerekçesiyle yasaklatması', 'Avrupa\'daki edebiyat akademilerinin yalnızca sade halk diliyle yazılmış eserlere uluslararası ödül vereceğini açıklaması', 'Darülfünun\'da Arapça ve Farsça sözlüklerin satılmasının kağıt vergisiyle durdurulması'], 'Selanik\'in ve Rumeli\'nin elden çıktığı Balkan Savaşları travması, \'Sanat şahsi ve muhteremdir\' diyen Fecriati kuşağını sarsmış ve neredeyse tamamını Millî Edebiyat ve Anadolu gerçekliğine yöneltmiştir.'),
  ('Ömer Seyfettin\'in \'Bahar ve Kelebekler\' adlı ünlü öyküsünde doksan yedi yaşındaki büyükannenin bahar güneşinde torunu genç kıza eski Türk kadınlarının neşeli ve sağlıklı yaşayışını anlatması hangi tezle bağlantılıdır?', 'Yabancı Fransız romanlarındaki karamsar \'asır sonu\' modasına özenen genç kızlara kendi ulusal kültürlerindeki yaşama sevincini hatırlatma teziyle', ['Kelebek koleksiyonculuğunun okullarda doğa bilimleri dersinin zorunlu uygulaması yapılması önerisiyle', 'Yaşlı kuşakların modern tıbba güvenmeyerek yalnızca şifalı bahar otlarıyla tedavi olmasını öven görüşle', 'Geleneksel konak mimarisinde kışlık ve yazlık odaların güneş yönüne göre planlanması ilkesiyle'], 'Genç Kalemler\'in \'Yeni Lisan\' makalesiyle aynı sayıda yayımlanan \'Bahar ve Kelebekler\', Yeni Lisan bildirisinin hikâye formundaki uygulamasıdır: Fransız romanı okuyan karamsar torun ile hayat dolu Türk ninesi karşılaştırılır.'),
  ('Ömer Seyfettin\'in Balkan Savaşları öncesinde Makedonya\'daki Bulgar çetecilerinin vahşetini Boris ve genç eşi Magda\'nın korkunç trajedisi üzerinden tüm çıplaklığıyla anlattığı sarsıcı öyküsü hangisidir?', 'Bomba', ['Kütük', 'Forsa', 'Kızılelma Niyazi'], 'Ömer Seyfettin\'in Balkanlardaki subaylık gözlemlerine dayanan \'Bomba\' öyküsünde komitacılar, örgütten ayrılıp Amerika\'ya göç etmek isteyen öğretmen Boris\'in kesik başını bez içinde hamile eşi Magda\'nın önüne bomba süsüyle bırakırlar.'),
  ('Ömer Seyfettin\'in Peçenek-Macar veya Osmanlı sınır savaşları geleneğine dayanan \'Başını Vermeyen Şehit\' öyküsünde Zigetvar yakınlarındaki Grijgal kalesi savunmasında olağanüstü kahramanlık gösteren gaziler kimlerdir?', 'Kuru Kadı, Deli Mehmet ve Deli Hüsrev', ['Cezmi, Adil Giray ve Perihan', 'Tosun Bey, Koca Ali ve Muhsin Çelebi', 'Hasan Bey, İhsan Bey ve Peyami'], 'Tarihçi Peçevi İbrahim Efendi\'nin vakayinamesinden esinlenen \'Başını Vermeyen Şehit\'te Deli Mehmet, kesilen başını düşman elinde bırakmayıp koltuğunun altına alarak Deli Hüsrev\'in yanına uzanır.'),
  ('Yakup Kadri Karaosmanoğlu\'nun Cumhuriyet devrimlerinin Anadolu toplumunda ve bürokraside nasıl algılandığını, Atatürk\'ün ölümünden Demokrat Parti\'nin iktidara gelişine kadar uzanan geniş bir kadroyla tartıştığı iki ciltlik romanı hangisidir?', 'Panorama', ['Sodom ve Gomore', 'Hüküm Gecesi', 'Nur Baba'], '1953-1954\'te iki cilt olarak yayımlanan \'Panorama\', devrimlerin şekilcilikte kalması, irticanın canlanması ve çok partili hayata geçiş sancılarını onlarca farklı toplumsal tip üzerinden sergiler.'),
];
